-- تصنيف بنود المسودات المزروعة (القطاعات والصناعات والأنشطة) بقوة الاستدلال.
-- لا يُحدَّث معيار إلا إذا بقيت بنوده مطابقة تمامًا للمسودة الأصلية، فلا يُمسّ ما عدّله المحرّرون.

UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "مشروعية الحيازة والانتفاع: أن يقوم النشاط على ملكٍ صحيح أو إذنٍ معتبر (امتياز، أو إقطاع، أو إجارة أرض، أو ترخيص صيد أو تعدين)، دون تعدٍّ على الملك العام أو الخاص أو المراعي والمياه المشتركة.", "en": "Lawful tenure and use: the activity must rest on valid ownership or a recognised permission (concession, land grant, land lease, fishing or mining licence), without encroaching on public or private property or shared pasture and water.", "ref": "أحكام إحياء الموات والإقطاع؛ حديث «الناس شركاء في ثلاث»", "strength": "ijtihad"}, {"kind": "condition", "ar": "عقود المزارعة والمساقاة والمغارسة: تُحدَّد حصة كل طرف جزءًا شائعًا من الناتج لا مقدارًا مقطوعًا، ويُبيَّن محل العقد والعمل والمدة وعلى من البذر والنفقات.", "en": "Muzara'ah, musaqah and mugharasah contracts: each party's share must be a common proportion of the output, not a fixed quantity; the subject, work, term and who bears seed and costs must be stated.", "ref": "معاملة النبي ﷺ أهل خيبر؛ قول جمهور الفقهاء بالجواز", "strength": "ijtihad"}, {"kind": "condition", "ar": "السَّلَم في المحاصيل والمنتجات: بيان الجنس والنوع والصفة والمقدار والأجل ومكان التسليم، وتسليم رأس المال في مجلس العقد، وألا يُعيَّن المُسلَم فيه من أرضٍ أو بستانٍ بعينه.", "en": "Salam in crops and produce: specify genus, type, quality, quantity, term and place of delivery; pay the capital at the contract session; and do not tie the subject to a specific plot or orchard.", "ref": "AAOIFI المعيار الشرعي 10 (السلم والسلم الموازي)", "strength": "ijma"}, {"kind": "prohibition", "ar": "بيع الثمار قبل بُدُوّ صلاحها بشرط التبقية، وبيع ما لا يُقدَر على تسليمه أو ما فيه غررٌ فاحش كالسمك في الماء قبل صيده.", "en": "Selling fruit before it ripens on condition that it stays on the tree, or selling what cannot be delivered or involves gross gharar, such as fish in the water before it is caught.", "ref": "النهي عن بيع الثمار حتى يبدو صلاحها؛ النهي عن بيع الغرر", "strength": "nass"}, {"kind": "mandatory", "ar": "في الإنتاج الحيواني: الذكاة الشرعية لما يُذبح، وطِيب العلف، ومنع تغذية الحيوان بالنجاسات حتى يصير جلّالًا ما لم يُحبس ويُطهَّر وفق المعتمد.", "en": "In livestock production: Shariah-compliant slaughter, wholesome feed, and no feeding on impurities that renders an animal jallalah unless it is confined and cleansed as approved.", "ref": "OIC/SMIIC 1 (متطلبات الغذاء الحلال)؛ أحكام الجلّالة", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "الإحسان إلى الحيوان: منع التعذيب، والتحميل فوق الطاقة، والحبس المؤذي، والتجويع، في التربية والنقل والذبح.", "en": "Kindness to animals: no torture, overloading, harmful confinement or starvation in rearing, transport or slaughter.", "ref": "حديث «إن الله كتب الإحسان على كل شيء»", "strength": "nass"}, {"kind": "mandatory", "ar": "حفظ الموارد ومنع الإفساد: لا استنزاف جائر للمياه والتربة والمخزون السمكي والغابات، ولا تلويث يضرّ بالجماعة أو الأجيال اللاحقة.", "en": "Protecting resources and preventing harm: no depletion of water, soil, fish stocks or forests, and no pollution that harms the community or later generations.", "ref": "قاعدة «لا ضرر ولا ضرار»؛ مقصدا حفظ النفس والمال", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "إنتاج ما يُتّخذ للمحرّم أو بيعه لمن يُعلم أو يغلب على الظن أنه يتخذه له، كبيع العنب لمصانع الخمر. وتُحال زراعة التبغ إلى الهيئة الشرعية لتفاوت الاجتهاد المعاصر فيها.", "en": "Producing what is used for the prohibited, or selling it to someone known or likely to use it so, such as grapes for wineries. Tobacco cultivation is referred to the Shariah board given differing contemporary opinions.", "ref": "قاعدة سدّ الذرائع؛ النهي عن الإعانة على الإثم", "strength": "ijtihad"}, {"kind": "condition", "ar": "وعاء الزكاة: الإفصاح عن الأصول الزكوية للنشاط، ومنها الزروع والثمار عند الحصاد (العشر فيما سُقي بلا مؤونة ونصفه فيما سُقي بمؤونة)، وبهيمة الأنعام السائمة، والمعادن والركاز، وفق منهجية تعتمدها الهيئة.", "en": "Zakat base: disclose the zakatable assets of the activity, including crops at harvest (a tenth when rain-fed, a twentieth when irrigated at cost), grazing livestock, and minerals and buried treasure, following a methodology approved by the board.", "ref": "AAOIFI المعيار الشرعي 35 (الزكاة)", "strength": "ijma"}, {"kind": "condition", "ar": "التمويل: يُقدَّم تمويل النشاط بصيغ مشروعة كالسلم والمزارعة والإجارة والمرابحة، ويخضع أي تمويل ربوي لحدود الفرز المالي في بوابة الأهلية.", "en": "Financing: use lawful structures such as salam, muzara'ah, ijarah and murabahah; any interest-bearing financing is subject to the eligibility gate's financial screens.", "ref": "AAOIFI المعيار الشرعي 21 (حدود الفرز)", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'sector' AND node_key = $v$p$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "مشروعية الحيازة والانتفاع: أن يقوم النشاط على ملكٍ صحيح أو إذنٍ معتبر (امتياز، أو إقطاع، أو إجارة أرض، أو ترخيص صيد أو تعدين)، دون تعدٍّ على الملك العام أو الخاص أو المراعي والمياه المشتركة.", "en": "Lawful tenure and use: the activity must rest on valid ownership or a recognised permission (concession, land grant, land lease, fishing or mining licence), without encroaching on public or private property or shared pasture and water.", "ref": "أحكام إحياء الموات والإقطاع؛ حديث «الناس شركاء في ثلاث»"}, {"kind": "condition", "ar": "عقود المزارعة والمساقاة والمغارسة: تُحدَّد حصة كل طرف جزءًا شائعًا من الناتج لا مقدارًا مقطوعًا، ويُبيَّن محل العقد والعمل والمدة وعلى من البذر والنفقات.", "en": "Muzara'ah, musaqah and mugharasah contracts: each party's share must be a common proportion of the output, not a fixed quantity; the subject, work, term and who bears seed and costs must be stated.", "ref": "معاملة النبي ﷺ أهل خيبر؛ قول جمهور الفقهاء بالجواز"}, {"kind": "condition", "ar": "السَّلَم في المحاصيل والمنتجات: بيان الجنس والنوع والصفة والمقدار والأجل ومكان التسليم، وتسليم رأس المال في مجلس العقد، وألا يُعيَّن المُسلَم فيه من أرضٍ أو بستانٍ بعينه.", "en": "Salam in crops and produce: specify genus, type, quality, quantity, term and place of delivery; pay the capital at the contract session; and do not tie the subject to a specific plot or orchard.", "ref": "AAOIFI المعيار الشرعي 10 (السلم والسلم الموازي)"}, {"kind": "prohibition", "ar": "بيع الثمار قبل بُدُوّ صلاحها بشرط التبقية، وبيع ما لا يُقدَر على تسليمه أو ما فيه غررٌ فاحش كالسمك في الماء قبل صيده.", "en": "Selling fruit before it ripens on condition that it stays on the tree, or selling what cannot be delivered or involves gross gharar, such as fish in the water before it is caught.", "ref": "النهي عن بيع الثمار حتى يبدو صلاحها؛ النهي عن بيع الغرر"}, {"kind": "mandatory", "ar": "في الإنتاج الحيواني: الذكاة الشرعية لما يُذبح، وطِيب العلف، ومنع تغذية الحيوان بالنجاسات حتى يصير جلّالًا ما لم يُحبس ويُطهَّر وفق المعتمد.", "en": "In livestock production: Shariah-compliant slaughter, wholesome feed, and no feeding on impurities that renders an animal jallalah unless it is confined and cleansed as approved.", "ref": "OIC/SMIIC 1 (متطلبات الغذاء الحلال)؛ أحكام الجلّالة"}, {"kind": "mandatory", "ar": "الإحسان إلى الحيوان: منع التعذيب، والتحميل فوق الطاقة، والحبس المؤذي، والتجويع، في التربية والنقل والذبح.", "en": "Kindness to animals: no torture, overloading, harmful confinement or starvation in rearing, transport or slaughter.", "ref": "حديث «إن الله كتب الإحسان على كل شيء»"}, {"kind": "mandatory", "ar": "حفظ الموارد ومنع الإفساد: لا استنزاف جائر للمياه والتربة والمخزون السمكي والغابات، ولا تلويث يضرّ بالجماعة أو الأجيال اللاحقة.", "en": "Protecting resources and preventing harm: no depletion of water, soil, fish stocks or forests, and no pollution that harms the community or later generations.", "ref": "قاعدة «لا ضرر ولا ضرار»؛ مقصدا حفظ النفس والمال"}, {"kind": "prohibition", "ar": "إنتاج ما يُتّخذ للمحرّم أو بيعه لمن يُعلم أو يغلب على الظن أنه يتخذه له، كبيع العنب لمصانع الخمر. وتُحال زراعة التبغ إلى الهيئة الشرعية لتفاوت الاجتهاد المعاصر فيها.", "en": "Producing what is used for the prohibited, or selling it to someone known or likely to use it so, such as grapes for wineries. Tobacco cultivation is referred to the Shariah board given differing contemporary opinions.", "ref": "قاعدة سدّ الذرائع؛ النهي عن الإعانة على الإثم"}, {"kind": "condition", "ar": "وعاء الزكاة: الإفصاح عن الأصول الزكوية للنشاط، ومنها الزروع والثمار عند الحصاد (العشر فيما سُقي بلا مؤونة ونصفه فيما سُقي بمؤونة)، وبهيمة الأنعام السائمة، والمعادن والركاز، وفق منهجية تعتمدها الهيئة.", "en": "Zakat base: disclose the zakatable assets of the activity, including crops at harvest (a tenth when rain-fed, a twentieth when irrigated at cost), grazing livestock, and minerals and buried treasure, following a methodology approved by the board.", "ref": "AAOIFI المعيار الشرعي 35 (الزكاة)"}, {"kind": "condition", "ar": "التمويل: يُقدَّم تمويل النشاط بصيغ مشروعة كالسلم والمزارعة والإجارة والمرابحة، ويخضع أي تمويل ربوي لحدود الفرز المالي في بوابة الأهلية.", "en": "Financing: use lawful structures such as salam, muzara'ah, ijarah and murabahah; any interest-bearing financing is subject to the eligibility gate's financial screens.", "ref": "AAOIFI المعيار الشرعي 21 (حدود الفرز)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "تصنيع المحرّمات لذاتها أو ما يغلب استعماله فيها: الخمور والمسكرات، ولحم الخنزير ومشتقاته، وأدوات القمار، والمواد الإباحية، وما لا منفعة مباحة فيه.", "en": "Manufacturing what is prohibited in itself or mainly used for it: alcohol and intoxicants, pork and its derivatives, gambling equipment, pornographic material, and anything without a lawful use.", "ref": "النهي عن الإعانة على الإثم والعدوان", "strength": "nass"}, {"kind": "mandatory", "ar": "حِلّ المُدخلات: التحقق من حِلّ المكوّنات والمضافات والمساعدات التصنيعية (كالجيلاتين والإنزيمات والكحول)، وتوثيق سلسلة الإمداد. ويُعمَل بالاستحالة والاستهلاك وفق ما تعتمده الهيئة.", "en": "Lawful inputs: verify ingredients, additives and processing aids (such as gelatin, enzymes and alcohol) and document the supply chain. Transformation (istihalah) and dilution (istihlak) apply as approved by the board.", "ref": "OIC/SMIIC 1 (الغذاء الحلال)", "strength": "ijtihad"}, {"kind": "condition", "ar": "الاستصناع: وصفٌ منضبط للمصنوع يرفع الجهالة، وتحديد الثمن وأجل التسليم. ويجوز تأجيل الثمن وتقسيطه، ويجوز الشرط الجزائي على التأخير في التسليم لا على تأخر سداد الديون.", "en": "Istisna': a precise description of the item that removes uncertainty, and a fixed price and delivery date. Price may be deferred or paid in instalments; a penalty clause may apply to late delivery but not to late payment of debts.", "ref": "AAOIFI المعيار الشرعي 11 (الاستصناع والاستصناع الموازي)", "strength": "ijma"}, {"kind": "condition", "ar": "عقود البناء والمقاولات: تحديد العمل والمواصفات والمدة والثمن، ويضمن المقاول ما تلف بتعدّيه أو تقصيره، ولا يضمن ما تلف بغير تعدٍّ.", "en": "Construction contracts: define the work, specifications, term and price; the contractor is liable for damage caused by transgression or negligence, not otherwise.", "ref": "أحكام الأجير المشترك والضمان", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "الوفاء بالمواصفات والجودة، وبيان العيوب، ومنع الغش والتدليس في المكوّنات والأوزان وبلد المنشأ.", "en": "Meet specifications and quality, disclose defects, and avoid fraud or misrepresentation in ingredients, weights and country of origin.", "ref": "حديث «من غشّنا فليس منّا»", "strength": "nass"}, {"kind": "mandatory", "ar": "حقوق العاملين: أجرٌ معلوم عادل يُدفع في وقته، وساعات عمل لا تُرهق، وسلامة مهنية، ومنع السُّخرة وعمل الأطفال الضار.", "en": "Workers' rights: a known, fair wage paid on time, reasonable hours, occupational safety, and no forced labour or harmful child labour.", "ref": "حديث «أعطوا الأجير أجره قبل أن يجفّ عرقه»؛ أحكام إجارة الأشخاص", "strength": "nass"}, {"kind": "mandatory", "ar": "السلامة والبيئة: إدارة الانبعاثات والنفايات والمواد الخطرة بما يمنع الضرر بالعاملين والجوار والبيئة.", "en": "Safety and environment: manage emissions, waste and hazardous materials so as to prevent harm to workers, neighbours and the environment.", "ref": "قاعدة «لا ضرر ولا ضرار»", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "الاحتكار والتواطؤ على الأسعار أو تقاسم الأسواق بما يضرّ بالناس.", "en": "Hoarding, price collusion or market sharing that harms people.", "ref": "حديث «لا يحتكر إلا خاطئ»", "strength": "nass"}, {"kind": "condition", "ar": "تمويل الأصول الثابتة: يُقدَّم تمويل المصانع والمعدات بصيغ مشروعة كالإجارة المنتهية بالتمليك والمرابحة والمشاركة المتناقصة، ويخضع أي تمويل ربوي لحدود الفرز المالي في بوابة الأهلية.", "en": "Fixed-asset financing: finance plants and equipment through lawful structures such as ijarah ending in ownership, murabahah and diminishing musharakah; any interest-bearing financing is subject to the eligibility gate's financial screens.", "ref": "AAOIFI المعايير الشرعية 8 (المرابحة) و9 (الإجارة) و12 (الشركة)", "strength": "ijtihad"}, {"kind": "recommended", "ar": "الحصول على شهادة حلال معتمدة للمنتجات الغذائية والدوائية ومستحضرات التجميل من جهة اعتماد معترف بها.", "en": "Obtain accredited halal certification for food, pharmaceutical and cosmetic products from a recognised certification body.", "ref": "OIC/SMIIC 2 و3 (متطلبات جهات الشهادة والاعتماد)", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'sector' AND node_key = $v$s$v$ AND requirements = $v$[{"kind": "prohibition", "ar": "تصنيع المحرّمات لذاتها أو ما يغلب استعماله فيها: الخمور والمسكرات، ولحم الخنزير ومشتقاته، وأدوات القمار، والمواد الإباحية، وما لا منفعة مباحة فيه.", "en": "Manufacturing what is prohibited in itself or mainly used for it: alcohol and intoxicants, pork and its derivatives, gambling equipment, pornographic material, and anything without a lawful use.", "ref": "النهي عن الإعانة على الإثم والعدوان"}, {"kind": "mandatory", "ar": "حِلّ المُدخلات: التحقق من حِلّ المكوّنات والمضافات والمساعدات التصنيعية (كالجيلاتين والإنزيمات والكحول)، وتوثيق سلسلة الإمداد. ويُعمَل بالاستحالة والاستهلاك وفق ما تعتمده الهيئة.", "en": "Lawful inputs: verify ingredients, additives and processing aids (such as gelatin, enzymes and alcohol) and document the supply chain. Transformation (istihalah) and dilution (istihlak) apply as approved by the board.", "ref": "OIC/SMIIC 1 (الغذاء الحلال)"}, {"kind": "condition", "ar": "الاستصناع: وصفٌ منضبط للمصنوع يرفع الجهالة، وتحديد الثمن وأجل التسليم. ويجوز تأجيل الثمن وتقسيطه، ويجوز الشرط الجزائي على التأخير في التسليم لا على تأخر سداد الديون.", "en": "Istisna': a precise description of the item that removes uncertainty, and a fixed price and delivery date. Price may be deferred or paid in instalments; a penalty clause may apply to late delivery but not to late payment of debts.", "ref": "AAOIFI المعيار الشرعي 11 (الاستصناع والاستصناع الموازي)"}, {"kind": "condition", "ar": "عقود البناء والمقاولات: تحديد العمل والمواصفات والمدة والثمن، ويضمن المقاول ما تلف بتعدّيه أو تقصيره، ولا يضمن ما تلف بغير تعدٍّ.", "en": "Construction contracts: define the work, specifications, term and price; the contractor is liable for damage caused by transgression or negligence, not otherwise.", "ref": "أحكام الأجير المشترك والضمان"}, {"kind": "mandatory", "ar": "الوفاء بالمواصفات والجودة، وبيان العيوب، ومنع الغش والتدليس في المكوّنات والأوزان وبلد المنشأ.", "en": "Meet specifications and quality, disclose defects, and avoid fraud or misrepresentation in ingredients, weights and country of origin.", "ref": "حديث «من غشّنا فليس منّا»"}, {"kind": "mandatory", "ar": "حقوق العاملين: أجرٌ معلوم عادل يُدفع في وقته، وساعات عمل لا تُرهق، وسلامة مهنية، ومنع السُّخرة وعمل الأطفال الضار.", "en": "Workers' rights: a known, fair wage paid on time, reasonable hours, occupational safety, and no forced labour or harmful child labour.", "ref": "حديث «أعطوا الأجير أجره قبل أن يجفّ عرقه»؛ أحكام إجارة الأشخاص"}, {"kind": "mandatory", "ar": "السلامة والبيئة: إدارة الانبعاثات والنفايات والمواد الخطرة بما يمنع الضرر بالعاملين والجوار والبيئة.", "en": "Safety and environment: manage emissions, waste and hazardous materials so as to prevent harm to workers, neighbours and the environment.", "ref": "قاعدة «لا ضرر ولا ضرار»"}, {"kind": "prohibition", "ar": "الاحتكار والتواطؤ على الأسعار أو تقاسم الأسواق بما يضرّ بالناس.", "en": "Hoarding, price collusion or market sharing that harms people.", "ref": "حديث «لا يحتكر إلا خاطئ»"}, {"kind": "condition", "ar": "تمويل الأصول الثابتة: يُقدَّم تمويل المصانع والمعدات بصيغ مشروعة كالإجارة المنتهية بالتمليك والمرابحة والمشاركة المتناقصة، ويخضع أي تمويل ربوي لحدود الفرز المالي في بوابة الأهلية.", "en": "Fixed-asset financing: finance plants and equipment through lawful structures such as ijarah ending in ownership, murabahah and diminishing musharakah; any interest-bearing financing is subject to the eligibility gate's financial screens.", "ref": "AAOIFI المعايير الشرعية 8 (المرابحة) و9 (الإجارة) و12 (الشركة)"}, {"kind": "recommended", "ar": "الحصول على شهادة حلال معتمدة للمنتجات الغذائية والدوائية ومستحضرات التجميل من جهة اعتماد معترف بها.", "en": "Obtain accredited halal certification for food, pharmaceutical and cosmetic products from a recognised certification body.", "ref": "OIC/SMIIC 2 و3 (متطلبات جهات الشهادة والاعتماد)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "تقديم خدمة محرّمة لذاتها أو الإعانة عليها أساسًا: خدمات القمار والمراهنات، وتقديم الخمور، والدعارة، والإقراض بفائدة.", "en": "Providing a service prohibited in itself or mainly supporting it: gambling and betting, serving alcohol, prostitution, and interest-based lending.", "ref": "النهي عن الإعانة على الإثم والعدوان", "strength": "nass"}, {"kind": "mandatory", "ar": "البيع والتجارة: ألا يبيع التاجر ما لا يملك، وأن يقبض ما يُشترط قبضه قبل بيعه، مع إعمال خيارات العيب والشرط.", "en": "Sales and trade: do not sell what you do not own, take possession where required before resale, and honour the options for defects and conditions.", "ref": "حديث «لا تبع ما ليس عندك»", "strength": "nass"}, {"kind": "prohibition", "ar": "بيع العِينة، والنجش، والغش، والتدليس، والاحتكار، وتلقّي الركبان على وجه الإضرار.", "en": "'Inah sales, bid rigging (najsh), fraud, misrepresentation, hoarding, and intercepting sellers before they reach the market to their detriment.", "ref": "النهي عن النجش والغش والاحتكار", "strength": "nass"}, {"kind": "mandatory", "ar": "الصرف ومبادلة الأثمان: التقابض في المجلس عند مبادلة العملات، ومنع الزيادة على الدين مقابل تأجيله. وما يُفرض من غرامات تأخير على المماطل يُصرف في وجوه الخير ولا يدخل في إيراد المنشأة.", "en": "Currency exchange: exchange currencies hand to hand at the contract session, and never add to a debt in return for deferral. Late-payment charges on a defaulting debtor go to charity and are not income.", "ref": "AAOIFI المعيار الشرعي 1 (المتاجرة في العملات)", "strength": "nass"}, {"kind": "condition", "ar": "إجارة المنافع والخدمات: بيان المنفعة والمدة والأجرة بيانًا نافيًا للجهالة، وتحمّل المؤجر ما يلزم لبقاء المنفعة.", "en": "Leasing of usufruct and services: specify the benefit, term and fee so as to remove uncertainty; the lessor bears what is needed to keep the benefit available.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)", "strength": "ijma"}, {"kind": "condition", "ar": "التأمين: يُقدَّم التأمين التكافلي على التأمين التجاري حيث يتاح، ويُفصَح عمّا يُلجأ إليه للحاجة أو الإلزام النظامي.", "en": "Insurance: prefer takaful to conventional insurance where available, and disclose any conventional cover taken out of need or legal obligation.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)", "strength": "ijma"}, {"kind": "condition", "ar": "الوساطة والعمولات: أن تكون العمولة معلومة، وألا تُربط أجرة الخدمة بمقدار قرضٍ أو أجله على نحوٍ يكون ذريعة إلى الربا.", "en": "Brokerage and commissions: the fee must be known, and service fees must not be tied to a loan's amount or term in a way that becomes a route to riba.", "ref": "قاعدة «كل قرض جرّ نفعًا فهو ربا»", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "أخلاقيات التسويق: الصدق في الوصف والسعر، ومنع التغرير والإعلانات المخالفة للآداب العامة أو المستهدِفة للقُصّر بما يضرّهم.", "en": "Marketing ethics: truthful descriptions and prices; no deception, and no advertising that breaches public morals or harmfully targets minors.", "ref": "حديث «البيّعان بالخيار… فإن صدقا وبيّنا بورك لهما»", "strength": "nass"}, {"kind": "mandatory", "ar": "حماية بيانات العملاء وخصوصيتهم: جمعها بإذن ولغرض مشروع، وعدم بيعها أو الانتفاع بها بغير رضا أصحابها.", "en": "Protect customer data and privacy: collect it with consent for a lawful purpose, and do not sell or exploit it without the owners' approval.", "ref": "أحكام الأمانة وحرمة التجسّس", "strength": "ijtihad"}, {"kind": "condition", "ar": "الأنشطة المختلطة: فصل الإيراد غير المباح في الحسابات وتطهيره، مع الالتزام بحدود الفرز المالي في بوابة الأهلية.", "en": "Mixed activities: separate non-permissible income in the accounts and purify it, within the eligibility gate's financial screens.", "ref": "AAOIFI المعيار الشرعي 21 (حدود الفرز والتطهير)", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'sector' AND node_key = $v$t$v$ AND requirements = $v$[{"kind": "prohibition", "ar": "تقديم خدمة محرّمة لذاتها أو الإعانة عليها أساسًا: خدمات القمار والمراهنات، وتقديم الخمور، والدعارة، والإقراض بفائدة.", "en": "Providing a service prohibited in itself or mainly supporting it: gambling and betting, serving alcohol, prostitution, and interest-based lending.", "ref": "النهي عن الإعانة على الإثم والعدوان"}, {"kind": "mandatory", "ar": "البيع والتجارة: ألا يبيع التاجر ما لا يملك، وأن يقبض ما يُشترط قبضه قبل بيعه، مع إعمال خيارات العيب والشرط.", "en": "Sales and trade: do not sell what you do not own, take possession where required before resale, and honour the options for defects and conditions.", "ref": "حديث «لا تبع ما ليس عندك»"}, {"kind": "prohibition", "ar": "بيع العِينة، والنجش، والغش، والتدليس، والاحتكار، وتلقّي الركبان على وجه الإضرار.", "en": "'Inah sales, bid rigging (najsh), fraud, misrepresentation, hoarding, and intercepting sellers before they reach the market to their detriment.", "ref": "النهي عن النجش والغش والاحتكار"}, {"kind": "mandatory", "ar": "الصرف ومبادلة الأثمان: التقابض في المجلس عند مبادلة العملات، ومنع الزيادة على الدين مقابل تأجيله. وما يُفرض من غرامات تأخير على المماطل يُصرف في وجوه الخير ولا يدخل في إيراد المنشأة.", "en": "Currency exchange: exchange currencies hand to hand at the contract session, and never add to a debt in return for deferral. Late-payment charges on a defaulting debtor go to charity and are not income.", "ref": "AAOIFI المعيار الشرعي 1 (المتاجرة في العملات)"}, {"kind": "condition", "ar": "إجارة المنافع والخدمات: بيان المنفعة والمدة والأجرة بيانًا نافيًا للجهالة، وتحمّل المؤجر ما يلزم لبقاء المنفعة.", "en": "Leasing of usufruct and services: specify the benefit, term and fee so as to remove uncertainty; the lessor bears what is needed to keep the benefit available.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)"}, {"kind": "condition", "ar": "التأمين: يُقدَّم التأمين التكافلي على التأمين التجاري حيث يتاح، ويُفصَح عمّا يُلجأ إليه للحاجة أو الإلزام النظامي.", "en": "Insurance: prefer takaful to conventional insurance where available, and disclose any conventional cover taken out of need or legal obligation.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)"}, {"kind": "condition", "ar": "الوساطة والعمولات: أن تكون العمولة معلومة، وألا تُربط أجرة الخدمة بمقدار قرضٍ أو أجله على نحوٍ يكون ذريعة إلى الربا.", "en": "Brokerage and commissions: the fee must be known, and service fees must not be tied to a loan's amount or term in a way that becomes a route to riba.", "ref": "قاعدة «كل قرض جرّ نفعًا فهو ربا»"}, {"kind": "mandatory", "ar": "أخلاقيات التسويق: الصدق في الوصف والسعر، ومنع التغرير والإعلانات المخالفة للآداب العامة أو المستهدِفة للقُصّر بما يضرّهم.", "en": "Marketing ethics: truthful descriptions and prices; no deception, and no advertising that breaches public morals or harmfully targets minors.", "ref": "حديث «البيّعان بالخيار… فإن صدقا وبيّنا بورك لهما»"}, {"kind": "mandatory", "ar": "حماية بيانات العملاء وخصوصيتهم: جمعها بإذن ولغرض مشروع، وعدم بيعها أو الانتفاع بها بغير رضا أصحابها.", "en": "Protect customer data and privacy: collect it with consent for a lawful purpose, and do not sell or exploit it without the owners' approval.", "ref": "أحكام الأمانة وحرمة التجسّس"}, {"kind": "condition", "ar": "الأنشطة المختلطة: فصل الإيراد غير المباح في الحسابات وتطهيره، مع الالتزام بحدود الفرز المالي في بوابة الأهلية.", "en": "Mixed activities: separate non-permissible income in the accounts and purify it, within the eligibility gate's financial screens.", "ref": "AAOIFI المعيار الشرعي 21 (حدود الفرز والتطهير)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "الحقوق المعنوية (الملكية الفكرية وبراءات الاختراع والعلامات والأسماء التجارية) حقوقٌ مالية معتبرة شرعًا: يُمنع الاعتداء عليها أو الانتفاع بها بغير إذن أصحابها.", "en": "Intellectual property (copyright, patents, trademarks and trade names) is a recognised financial right: it must not be infringed or used without the owner's permission.", "ref": "قرار مجمع الفقه الإسلامي الدولي بشأن الحقوق المعنوية", "strength": "ijma"}, {"kind": "condition", "ar": "عقود البرمجيات والتراخيص والاشتراكات: وصف منضبط للخدمة ومستوى أدائها ومدتها وأجرتها. وتُكيَّف البرمجيات المخصّصة استصناعًا، والاشتراكات إجارةَ منافع.", "en": "Software, licensing and subscription contracts: a precise description of the service, its performance level, term and fee. Custom software is treated as istisna', subscriptions as a lease of usufruct.", "ref": "AAOIFI المعياران الشرعيان 9 (الإجارة) و11 (الاستصناع)", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "تطوير منصات القمار والمراهنات أو تشغيلها، وكذلك المحتوى الإباحي، وتطبيقات الإقراض بفائدة، وألعاب الحظ المدفوعة المبنية على الغرر.", "en": "Building or operating gambling and betting platforms, pornographic content, interest-based lending apps, or paid games of chance built on gharar.", "ref": "تحريم الميسر والربا", "strength": "nass"}, {"kind": "mandatory", "ar": "البيانات والخصوصية: جمع البيانات بإذنٍ ولغرضٍ مشروع، وعدم بيعها أو توظيفها بما يخالف الأمانة، والإفصاح عن سياسات استخدامها.", "en": "Data and privacy: collect data with consent for a lawful purpose, do not sell or use it in breach of trust, and disclose how it is used.", "ref": "أحكام الأمانة وحرمة التجسّس", "strength": "ijtihad"}, {"kind": "condition", "ar": "الأصول الرقمية والعملات المشفّرة في وضع «قيد الدراسة / إحالة» ما لم تصدر الهيئة قرارًا فيها. ويُمنع التداول بالهامش القائم على القروض الربوية والمشتقات القائمة على الرهان.", "en": "Digital assets and cryptocurrencies stay \"under study / referral\" until the board rules. Margin trading funded by interest-bearing loans and betting-based derivatives are not permitted.", "ref": "مرجعية المعيار: قرار مجمع الفقه 237 بالتوقف وطلب مزيد من الدراسة", "strength": "khilaf"}, {"kind": "condition", "ar": "الذكاء الاصطناعي والخوارزميات: الشفافية وعدم التضليل، ومنع التحيّز الضار، ومسؤولية المشغّل عمّا تُحدثه الأنظمة من ضرر، وعدم نسبة الفتوى أو الحكم الشرعي إلى النظام الآلي.", "en": "Artificial intelligence and algorithms: transparency and no deception, preventing harmful bias, operator liability for harm caused by the system, and never attributing a fatwa or Shariah ruling to an automated system.", "ref": "قاعدة «لا ضرر ولا ضرار»؛ مبدأ المساءلة", "strength": "ijtihad"}, {"kind": "condition", "ar": "البحث العلمي: الالتزام بأخلاقيات البحث وحفظ النفس والكرامة الإنسانية، وأخذ الموافقة المستنيرة، ومنع التجارب المحرّمة كالاستنساخ البشري.", "en": "Scientific research: follow research ethics, protect life and human dignity, obtain informed consent, and prohibit forbidden experiments such as human cloning.", "ref": "مقصدا حفظ النفس والنسل", "strength": "ijma"}, {"kind": "condition", "ar": "الإيرادات الإعلانية: التحقق من مشروعية المعلَن عنه، وتطهير ما يرد من إعلانات محرّمة إن تعذّر منعها ابتداءً.", "en": "Advertising revenue: verify that what is advertised is lawful, and purify income from prohibited adverts that could not be blocked in advance.", "ref": "AAOIFI المعيار الشرعي 21 (التطهير)", "strength": "ijtihad"}, {"kind": "condition", "ar": "تمويل الشركات الناشئة: صيغ المشاركة والمضاربة. ويُتجنّب الأسهم الممتازة ذات العائد المضمون، والقروض القابلة للتحويل بفائدة.", "en": "Start-up financing: musharakah and mudarabah structures; avoid preferred shares with guaranteed returns and interest-bearing convertible notes.", "ref": "AAOIFI المعياران الشرعيان 12 (الشركة) و13 (المضاربة)", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'sector' AND node_key = $v$q$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "الحقوق المعنوية (الملكية الفكرية وبراءات الاختراع والعلامات والأسماء التجارية) حقوقٌ مالية معتبرة شرعًا: يُمنع الاعتداء عليها أو الانتفاع بها بغير إذن أصحابها.", "en": "Intellectual property (copyright, patents, trademarks and trade names) is a recognised financial right: it must not be infringed or used without the owner's permission.", "ref": "قرار مجمع الفقه الإسلامي الدولي بشأن الحقوق المعنوية"}, {"kind": "condition", "ar": "عقود البرمجيات والتراخيص والاشتراكات: وصف منضبط للخدمة ومستوى أدائها ومدتها وأجرتها. وتُكيَّف البرمجيات المخصّصة استصناعًا، والاشتراكات إجارةَ منافع.", "en": "Software, licensing and subscription contracts: a precise description of the service, its performance level, term and fee. Custom software is treated as istisna', subscriptions as a lease of usufruct.", "ref": "AAOIFI المعياران الشرعيان 9 (الإجارة) و11 (الاستصناع)"}, {"kind": "prohibition", "ar": "تطوير منصات القمار والمراهنات أو تشغيلها، وكذلك المحتوى الإباحي، وتطبيقات الإقراض بفائدة، وألعاب الحظ المدفوعة المبنية على الغرر.", "en": "Building or operating gambling and betting platforms, pornographic content, interest-based lending apps, or paid games of chance built on gharar.", "ref": "تحريم الميسر والربا"}, {"kind": "mandatory", "ar": "البيانات والخصوصية: جمع البيانات بإذنٍ ولغرضٍ مشروع، وعدم بيعها أو توظيفها بما يخالف الأمانة، والإفصاح عن سياسات استخدامها.", "en": "Data and privacy: collect data with consent for a lawful purpose, do not sell or use it in breach of trust, and disclose how it is used.", "ref": "أحكام الأمانة وحرمة التجسّس"}, {"kind": "condition", "ar": "الأصول الرقمية والعملات المشفّرة في وضع «قيد الدراسة / إحالة» ما لم تصدر الهيئة قرارًا فيها. ويُمنع التداول بالهامش القائم على القروض الربوية والمشتقات القائمة على الرهان.", "en": "Digital assets and cryptocurrencies stay \"under study / referral\" until the board rules. Margin trading funded by interest-bearing loans and betting-based derivatives are not permitted.", "ref": "مرجعية المعيار: قرار مجمع الفقه 237 بالتوقف وطلب مزيد من الدراسة"}, {"kind": "condition", "ar": "الذكاء الاصطناعي والخوارزميات: الشفافية وعدم التضليل، ومنع التحيّز الضار، ومسؤولية المشغّل عمّا تُحدثه الأنظمة من ضرر، وعدم نسبة الفتوى أو الحكم الشرعي إلى النظام الآلي.", "en": "Artificial intelligence and algorithms: transparency and no deception, preventing harmful bias, operator liability for harm caused by the system, and never attributing a fatwa or Shariah ruling to an automated system.", "ref": "قاعدة «لا ضرر ولا ضرار»؛ مبدأ المساءلة"}, {"kind": "condition", "ar": "البحث العلمي: الالتزام بأخلاقيات البحث وحفظ النفس والكرامة الإنسانية، وأخذ الموافقة المستنيرة، ومنع التجارب المحرّمة كالاستنساخ البشري.", "en": "Scientific research: follow research ethics, protect life and human dignity, obtain informed consent, and prohibit forbidden experiments such as human cloning.", "ref": "مقصدا حفظ النفس والنسل"}, {"kind": "condition", "ar": "الإيرادات الإعلانية: التحقق من مشروعية المعلَن عنه، وتطهير ما يرد من إعلانات محرّمة إن تعذّر منعها ابتداءً.", "en": "Advertising revenue: verify that what is advertised is lawful, and purify income from prohibited adverts that could not be blocked in advance.", "ref": "AAOIFI المعيار الشرعي 21 (التطهير)"}, {"kind": "condition", "ar": "تمويل الشركات الناشئة: صيغ المشاركة والمضاربة. ويُتجنّب الأسهم الممتازة ذات العائد المضمون، والقروض القابلة للتحويل بفائدة.", "en": "Start-up financing: musharakah and mudarabah structures; avoid preferred shares with guaranteed returns and interest-bearing convertible notes.", "ref": "AAOIFI المعياران الشرعيان 12 (الشركة) و13 (المضاربة)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "العدل وأداء الأمانة في الولايات العامة والخاصة، وتقديم الأكفأ الأمين في المسؤوليات.", "en": "Justice and faithful discharge of trust in public and private office, appointing the most competent and trustworthy.", "ref": "قوله تعالى: ﴿إن الله يأمركم أن تؤدوا الأمانات إلى أهلها﴾", "strength": "nass"}, {"kind": "mandatory", "ar": "الشورى والحوكمة: فصل الصلاحيات، وتوثيق القرارات، والإفصاح الدوري عن الأداء والمخاطر.", "en": "Consultation and governance: separation of powers, documented decisions, and regular disclosure of performance and risks.", "ref": "قوله تعالى: ﴿وأمرهم شورى بينهم﴾", "strength": "nass"}, {"kind": "prohibition", "ar": "الرشوة، والمحاباة، واستغلال النفوذ، وقبول الهدايا بسبب الولاية.", "en": "Bribery, favouritism, abuse of influence, and accepting gifts because of one's office.", "ref": "حديث «لعن رسول الله ﷺ الراشي والمرتشي»؛ حديث ابن اللُّتبيّة", "strength": "nass"}, {"kind": "mandatory", "ar": "منع تعارض المصالح: الإفصاح عن المصالح الشخصية، وتنحّي صاحب المصلحة عن القرار المتصل بها.", "en": "Preventing conflicts of interest: disclose personal interests, and recuse the interested party from related decisions.", "ref": "قاعدة سدّ الذرائع", "strength": "ijtihad"}, {"kind": "condition", "ar": "السياسات الاقتصادية والتنظيمية: ألا تُلزِم بالتعامل بالربا أو الغرر أو تشجّع عليه حيث توجد بدائل مشروعة، وأن تُبنى على المصلحة المعتبرة ومقاصد الشريعة.", "en": "Economic and regulatory policy: do not mandate or encourage dealing in riba or gharar where lawful alternatives exist, and base policy on recognised public interest and the objectives of Shariah.", "ref": "قاعدة «تصرّف الإمام على الرعية منوطٌ بالمصلحة»", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "المال العام والأوقاف: حفظ الأصل وتنميته بالصيغ المشروعة، وصرف الريع وفق شرط الواقف أو المصلحة العامة، مع المحاسبة والتدقيق المستقل.", "en": "Public funds and awqaf: preserve and grow the principal through lawful structures, spend the income per the endower's conditions or the public interest, with independent accounting and audit.", "ref": "AAOIFI المعيار الشرعي 33 (الوقف)؛ قاعدة «شرط الواقف كنصّ الشارع»", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "الرقابة الشرعية المستقلة للجهات المرجعية، وإعلان مناهج الترجيح والاجتهاد، ونشر القرارات بأرقامها وأدلتها.", "en": "Independent Shariah oversight of reference bodies, with published methods of preference and ijtihad, and decisions published with their numbers and evidence.", "ref": "مبدأ الشفافية في المعيار", "strength": "ijtihad"}, {"kind": "recommended", "ar": "الاستشارات الاستراتيجية: الامتناع عن تقديم المشورة لمشروعاتٍ محرّمة، وتقديم البدائل المشروعة عند الإمكان.", "en": "Strategic advisory: decline to advise on prohibited projects, and propose lawful alternatives where possible.", "ref": "النهي عن الإعانة على الإثم", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'sector' AND node_key = $v$n$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "العدل وأداء الأمانة في الولايات العامة والخاصة، وتقديم الأكفأ الأمين في المسؤوليات.", "en": "Justice and faithful discharge of trust in public and private office, appointing the most competent and trustworthy.", "ref": "قوله تعالى: ﴿إن الله يأمركم أن تؤدوا الأمانات إلى أهلها﴾"}, {"kind": "mandatory", "ar": "الشورى والحوكمة: فصل الصلاحيات، وتوثيق القرارات، والإفصاح الدوري عن الأداء والمخاطر.", "en": "Consultation and governance: separation of powers, documented decisions, and regular disclosure of performance and risks.", "ref": "قوله تعالى: ﴿وأمرهم شورى بينهم﴾"}, {"kind": "prohibition", "ar": "الرشوة، والمحاباة، واستغلال النفوذ، وقبول الهدايا بسبب الولاية.", "en": "Bribery, favouritism, abuse of influence, and accepting gifts because of one's office.", "ref": "حديث «لعن رسول الله ﷺ الراشي والمرتشي»؛ حديث ابن اللُّتبيّة"}, {"kind": "mandatory", "ar": "منع تعارض المصالح: الإفصاح عن المصالح الشخصية، وتنحّي صاحب المصلحة عن القرار المتصل بها.", "en": "Preventing conflicts of interest: disclose personal interests, and recuse the interested party from related decisions.", "ref": "قاعدة سدّ الذرائع"}, {"kind": "condition", "ar": "السياسات الاقتصادية والتنظيمية: ألا تُلزِم بالتعامل بالربا أو الغرر أو تشجّع عليه حيث توجد بدائل مشروعة، وأن تُبنى على المصلحة المعتبرة ومقاصد الشريعة.", "en": "Economic and regulatory policy: do not mandate or encourage dealing in riba or gharar where lawful alternatives exist, and base policy on recognised public interest and the objectives of Shariah.", "ref": "قاعدة «تصرّف الإمام على الرعية منوطٌ بالمصلحة»"}, {"kind": "mandatory", "ar": "المال العام والأوقاف: حفظ الأصل وتنميته بالصيغ المشروعة، وصرف الريع وفق شرط الواقف أو المصلحة العامة، مع المحاسبة والتدقيق المستقل.", "en": "Public funds and awqaf: preserve and grow the principal through lawful structures, spend the income per the endower's conditions or the public interest, with independent accounting and audit.", "ref": "AAOIFI المعيار الشرعي 33 (الوقف)؛ قاعدة «شرط الواقف كنصّ الشارع»"}, {"kind": "mandatory", "ar": "الرقابة الشرعية المستقلة للجهات المرجعية، وإعلان مناهج الترجيح والاجتهاد، ونشر القرارات بأرقامها وأدلتها.", "en": "Independent Shariah oversight of reference bodies, with published methods of preference and ijtihad, and decisions published with their numbers and evidence.", "ref": "مبدأ الشفافية في المعيار"}, {"kind": "recommended", "ar": "الاستشارات الاستراتيجية: الامتناع عن تقديم المشورة لمشروعاتٍ محرّمة، وتقديم البدائل المشروعة عند الإمكان.", "en": "Strategic advisory: decline to advise on prohibited projects, and propose lawful alternatives where possible.", "ref": "النهي عن الإعانة على الإثم"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "زكاة الزروع والثمار: العُشر فيما سُقي بلا مؤونة ونصف العُشر فيما سُقي بمؤونة، بعد بلوغ النصاب (خمسة أوسق)، وتُخرج عند الحصاد. ويُفصح النشاط عن وعاء الزكاة ولو كانت تُخرج على مستوى الملّاك.", "en": "Zakat on crops: a tenth when rain-fed and a twentieth when irrigated at cost, once the nisab (five awsuq) is reached, due at harvest. The activity discloses its zakat base even if owners pay it.", "ref": "AAOIFI المعيار الشرعي 35 (الزكاة)", "strength": "ijma"}, {"kind": "mandatory", "ar": "الذكاة الشرعية في المسالخ والمزارع التي تذبح، وأحكام الصيد: التسمية، وكون الصائد من أهل الذكاة، وعدم قتل الصيد بالخنق أو الصعق المميت قبل الذكاة.", "en": "Shariah-compliant slaughter in abattoirs and farms that slaughter, and hunting rules: invoking God's name, a qualified hunter, and no killing by strangling or lethal stunning before slaughter.", "ref": "OIC/SMIIC 1 (الغذاء الحلال)", "strength": "ijma"}, {"kind": "prohibition", "ar": "استعمال أعلاف تحتوي على لحم الخنزير أو مشتقاته أو الدم المسفوح أو مخلّفات الحيوانات غير المذكاة على نحو يجعل الحيوان جلّالة، دون حبسٍ وتطهير.", "en": "Using feed containing pork or its derivatives, flowing blood, or remains of unslaughtered animals such that the animal becomes jallalah, without confinement and cleansing.", "ref": "أحكام الجلّالة", "strength": "ijtihad"}, {"kind": "condition", "ar": "تمويل المواسم الزراعية بالسلم أو المزارعة أو المساقاة أو الإجارة. ولا يجوز أن تكون حصة الممول مبلغًا مقطوعًا يضمن له ربحًا.", "en": "Seasonal financing through salam, muzara'ah, musaqah or ijarah. The financier's share may not be a fixed sum that guarantees a profit.", "ref": "AAOIFI المعيار الشرعي 10 (السلم)", "strength": "ijtihad"}, {"kind": "condition", "ar": "بيع المحاصيل والمواشي: بيان المبيع بالوصف أو الرؤية، وجواز بيع الزرع بعد اشتداد الحب، والمواشي بالعدّ أو الوزن مع بيان العيوب.", "en": "Selling crops and livestock: identify the goods by description or inspection; standing crops may be sold once the grain has hardened, and livestock by head or weight with defects disclosed.", "ref": "النهي عن بيع الحب حتى يشتد", "strength": "nass"}, {"kind": "mandatory", "ar": "الإحسان إلى الحيوان في التربية المكثفة: مساحةٌ وتهوية وعلف وماء كافٍ، ومنع التشويه والإيذاء غير الضروري.", "en": "Kindness in intensive farming: adequate space, ventilation, feed and water, and no unnecessary mutilation or harm.", "ref": "حديث «في كل كبدٍ رطبة أجر»", "strength": "nass"}, {"kind": "condition", "ar": "المبيدات والأسمدة والهندسة الوراثية: تُستعمل بما لا يضرّ بالإنسان والبيئة، وتُحال المحاصيل المعدّلة وراثيًا المثيرة للخلاف إلى الهيئة.", "en": "Pesticides, fertilisers and genetic engineering: use them without harming people or the environment; contested genetically modified crops are referred to the board.", "ref": "قاعدة «لا ضرر ولا ضرار»", "strength": "khilaf"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$A$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "زكاة الزروع والثمار: العُشر فيما سُقي بلا مؤونة ونصف العُشر فيما سُقي بمؤونة، بعد بلوغ النصاب (خمسة أوسق)، وتُخرج عند الحصاد. ويُفصح النشاط عن وعاء الزكاة ولو كانت تُخرج على مستوى الملّاك.", "en": "Zakat on crops: a tenth when rain-fed and a twentieth when irrigated at cost, once the nisab (five awsuq) is reached, due at harvest. The activity discloses its zakat base even if owners pay it.", "ref": "AAOIFI المعيار الشرعي 35 (الزكاة)"}, {"kind": "mandatory", "ar": "الذكاة الشرعية في المسالخ والمزارع التي تذبح، وأحكام الصيد: التسمية، وكون الصائد من أهل الذكاة، وعدم قتل الصيد بالخنق أو الصعق المميت قبل الذكاة.", "en": "Shariah-compliant slaughter in abattoirs and farms that slaughter, and hunting rules: invoking God's name, a qualified hunter, and no killing by strangling or lethal stunning before slaughter.", "ref": "OIC/SMIIC 1 (الغذاء الحلال)"}, {"kind": "prohibition", "ar": "استعمال أعلاف تحتوي على لحم الخنزير أو مشتقاته أو الدم المسفوح أو مخلّفات الحيوانات غير المذكاة على نحو يجعل الحيوان جلّالة، دون حبسٍ وتطهير.", "en": "Using feed containing pork or its derivatives, flowing blood, or remains of unslaughtered animals such that the animal becomes jallalah, without confinement and cleansing.", "ref": "أحكام الجلّالة"}, {"kind": "condition", "ar": "تمويل المواسم الزراعية بالسلم أو المزارعة أو المساقاة أو الإجارة. ولا يجوز أن تكون حصة الممول مبلغًا مقطوعًا يضمن له ربحًا.", "en": "Seasonal financing through salam, muzara'ah, musaqah or ijarah. The financier's share may not be a fixed sum that guarantees a profit.", "ref": "AAOIFI المعيار الشرعي 10 (السلم)"}, {"kind": "condition", "ar": "بيع المحاصيل والمواشي: بيان المبيع بالوصف أو الرؤية، وجواز بيع الزرع بعد اشتداد الحب، والمواشي بالعدّ أو الوزن مع بيان العيوب.", "en": "Selling crops and livestock: identify the goods by description or inspection; standing crops may be sold once the grain has hardened, and livestock by head or weight with defects disclosed.", "ref": "النهي عن بيع الحب حتى يشتد"}, {"kind": "mandatory", "ar": "الإحسان إلى الحيوان في التربية المكثفة: مساحةٌ وتهوية وعلف وماء كافٍ، ومنع التشويه والإيذاء غير الضروري.", "en": "Kindness in intensive farming: adequate space, ventilation, feed and water, and no unnecessary mutilation or harm.", "ref": "حديث «في كل كبدٍ رطبة أجر»"}, {"kind": "condition", "ar": "المبيدات والأسمدة والهندسة الوراثية: تُستعمل بما لا يضرّ بالإنسان والبيئة، وتُحال المحاصيل المعدّلة وراثيًا المثيرة للخلاف إلى الهيئة.", "en": "Pesticides, fertilisers and genetic engineering: use them without harming people or the environment; contested genetically modified crops are referred to the board.", "ref": "قاعدة «لا ضرر ولا ضرار»"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "مراعاة الملك العام: المعادن الظاهرة والموارد المشتركة كالماء والكلأ والنار لا يُحتكر أصلها، ويكون الاستغلال بإذن وليّ الأمر وبعقدٍ يحفظ حق الجماعة.", "en": "Respect public ownership: surface minerals and shared resources such as water, pasture and fuel may not be monopolised; exploitation requires the authority's permission under a contract that protects the community's rights.", "ref": "حديث «الناس شركاء في ثلاث: الماء والكلأ والنار»", "strength": "nass"}, {"kind": "condition", "ar": "عقود الامتياز والمشاركة في الإنتاج: بيان محل الامتياز ومدته والتزامات الطرفين، وأن تكون حصة الدولة أو الشريك نسبةً من الإنتاج أو أجرةً معلومة لا فائدةً على تمويل.", "en": "Concession and production-sharing contracts: specify the subject, term and obligations; the state's or partner's share must be a share of output or a known fee, not interest on financing.", "ref": "AAOIFI المعيار الشرعي 22 (عقود الامتياز)", "strength": "ijtihad"}, {"kind": "condition", "ar": "زكاة المعادن والركاز: يُفصح عن المستخرَج، ويُحال تحديد الواجب (ربع العشر في المعدن أو الخُمس في الركاز) والنصاب إلى منهجية الهيئة، لاختلاف المذاهب.", "en": "Zakat on minerals and buried treasure: disclose what is extracted; the rate (a fortieth on minerals or a fifth on buried treasure) and nisab follow the board's methodology given differences among schools.", "ref": "AAOIFI المعيار الشرعي 35 (الزكاة)", "strength": "khilaf"}, {"kind": "mandatory", "ar": "السلامة المهنية في المناجم والمنصات والمحطات: معدات الوقاية، وخطط الطوارئ، وعدم تعريض العمال لخطرٍ غالب.", "en": "Occupational safety in mines, rigs and plants: protective equipment, emergency plans, and no exposure of workers to likely danger.", "ref": "قوله تعالى: ﴿ولا تلقوا بأيديكم إلى التهلكة﴾", "strength": "nass"}, {"kind": "mandatory", "ar": "حماية البيئة: إعادة تأهيل مواقع التعدين، ومنع تسرّب النفط والمخلّفات الخطرة، وإدارة الانبعاثات.", "en": "Environmental protection: rehabilitate mining sites, prevent oil spills and hazardous waste leaks, and manage emissions.", "ref": "قاعدة «الضرر يُزال»", "strength": "ijtihad"}, {"kind": "condition", "ar": "بيع النفط والغاز والكهرباء: جواز البيع الآجل والتوريد بمواصفات منضبطة، واجتناب المشتقات القائمة على المضاربة على الفروق دون تسليم.", "en": "Selling oil, gas and electricity: forward sales and supply contracts with precise specifications are permitted; avoid derivatives that speculate on price differences without delivery.", "ref": "AAOIFI المعيار الشرعي 20 (بيع السلع في الأسواق المنظمة)", "strength": "ijtihad"}, {"kind": "recommended", "ar": "تفضيل الطاقة المتجددة وترشيد استهلاك الموارد غير المتجددة رعايةً لحق الأجيال القادمة.", "en": "Prefer renewable energy and conserve non-renewable resources out of regard for future generations.", "ref": "مقصد حفظ المال ونهي الإسراف", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$B$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "مراعاة الملك العام: المعادن الظاهرة والموارد المشتركة كالماء والكلأ والنار لا يُحتكر أصلها، ويكون الاستغلال بإذن وليّ الأمر وبعقدٍ يحفظ حق الجماعة.", "en": "Respect public ownership: surface minerals and shared resources such as water, pasture and fuel may not be monopolised; exploitation requires the authority's permission under a contract that protects the community's rights.", "ref": "حديث «الناس شركاء في ثلاث: الماء والكلأ والنار»"}, {"kind": "condition", "ar": "عقود الامتياز والمشاركة في الإنتاج: بيان محل الامتياز ومدته والتزامات الطرفين، وأن تكون حصة الدولة أو الشريك نسبةً من الإنتاج أو أجرةً معلومة لا فائدةً على تمويل.", "en": "Concession and production-sharing contracts: specify the subject, term and obligations; the state's or partner's share must be a share of output or a known fee, not interest on financing.", "ref": "AAOIFI المعيار الشرعي 22 (عقود الامتياز)"}, {"kind": "condition", "ar": "زكاة المعادن والركاز: يُفصح عن المستخرَج، ويُحال تحديد الواجب (ربع العشر في المعدن أو الخُمس في الركاز) والنصاب إلى منهجية الهيئة، لاختلاف المذاهب.", "en": "Zakat on minerals and buried treasure: disclose what is extracted; the rate (a fortieth on minerals or a fifth on buried treasure) and nisab follow the board's methodology given differences among schools.", "ref": "AAOIFI المعيار الشرعي 35 (الزكاة)"}, {"kind": "mandatory", "ar": "السلامة المهنية في المناجم والمنصات والمحطات: معدات الوقاية، وخطط الطوارئ، وعدم تعريض العمال لخطرٍ غالب.", "en": "Occupational safety in mines, rigs and plants: protective equipment, emergency plans, and no exposure of workers to likely danger.", "ref": "قوله تعالى: ﴿ولا تلقوا بأيديكم إلى التهلكة﴾"}, {"kind": "mandatory", "ar": "حماية البيئة: إعادة تأهيل مواقع التعدين، ومنع تسرّب النفط والمخلّفات الخطرة، وإدارة الانبعاثات.", "en": "Environmental protection: rehabilitate mining sites, prevent oil spills and hazardous waste leaks, and manage emissions.", "ref": "قاعدة «الضرر يُزال»"}, {"kind": "condition", "ar": "بيع النفط والغاز والكهرباء: جواز البيع الآجل والتوريد بمواصفات منضبطة، واجتناب المشتقات القائمة على المضاربة على الفروق دون تسليم.", "en": "Selling oil, gas and electricity: forward sales and supply contracts with precise specifications are permitted; avoid derivatives that speculate on price differences without delivery.", "ref": "AAOIFI المعيار الشرعي 20 (بيع السلع في الأسواق المنظمة)"}, {"kind": "recommended", "ar": "تفضيل الطاقة المتجددة وترشيد استهلاك الموارد غير المتجددة رعايةً لحق الأجيال القادمة.", "en": "Prefer renewable energy and conserve non-renewable resources out of regard for future generations.", "ref": "مقصد حفظ المال ونهي الإسراف"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "في الصناعات الغذائية: خلوّ المنتج من لحم الخنزير والكحول المسكر والدم ومشتقات الحيوان غير المذكّى، وفصل خطوط الإنتاج أو تطهيرها عند الاشتراك.", "en": "In food manufacturing: products must be free of pork, intoxicating alcohol, blood and derivatives of unslaughtered animals, with production lines separated or cleansed when shared.", "ref": "OIC/SMIIC 1 (الغذاء الحلال)", "strength": "nass"}, {"kind": "condition", "ar": "في الصناعات الدوائية: التداوي بالمباح أصلٌ. ويُحال استعمال المواد المحرّمة غير المستحيلة إلى الهيئة، ويُقبل للضرورة عند انعدام البديل.", "en": "In pharmaceuticals: treatment with lawful substances is the rule. Use of untransformed prohibited substances is referred to the board and accepted only of necessity when no alternative exists.", "ref": "قاعدة «الضرورات تبيح المحظورات» مع تقديرها بقدرها", "strength": "khilaf"}, {"kind": "condition", "ar": "في مستحضرات التجميل: التحقق من مصدر الكولاجين والجيلاتين والدهون الحيوانية، وخلوّها من النجاسات.", "en": "In cosmetics: verify the source of collagen, gelatin and animal fats, and ensure freedom from impurities.", "ref": "OIC/SMIIC 4 (مستحضرات التجميل الحلال)", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "تصنيع الأسلحة أو المواد الكيميائية لبيعها لمن يُعلم أنه يستعملها في العدوان أو الإرهاب، وتصنيع أدوات القمار والتماثيل المعبودة.", "en": "Manufacturing weapons or chemicals for sale to those known to use them for aggression or terrorism, and making gambling devices or idols.", "ref": "النهي عن الإعانة على الإثم والعدوان", "strength": "nass"}, {"kind": "condition", "ar": "التصنيع للغير: يكيَّف استصناعًا أو إجارة أشخاص، ويُحدَّد فيه ملك المواد وضمانها وأجرة الصنعة.", "en": "Contract manufacturing is structured as istisna' or hiring of services, stating who owns the materials, who bears their risk, and the manufacturing fee.", "ref": "AAOIFI المعياران الشرعيان 11 (الاستصناع) و34 (إجارة الأشخاص)", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "الوسم والتغليف: بيان المكونات وبلد المنشأ وتاريخ الصلاحية بصدق، ومنع وضع علامة حلال دون شهادة معتمدة.", "en": "Labelling and packaging: state ingredients, country of origin and expiry truthfully, and never display a halal mark without accredited certification.", "ref": "حديث «من غشّنا فليس منّا»", "strength": "nass"}, {"kind": "condition", "ar": "المنتجات مزدوجة الاستعمال (كالكحول الصناعي والكيماويات): يجوز تصنيعها لمنافعها المباحة، مع ضوابط بيعٍ تمنع توجيهها إلى المحرّم.", "en": "Dual-use products (such as industrial alcohol and chemicals) may be made for lawful uses, with sales controls that prevent diversion to prohibited ends.", "ref": "قاعدة «الأمور بمقاصدها» وسدّ الذرائع", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$C$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "في الصناعات الغذائية: خلوّ المنتج من لحم الخنزير والكحول المسكر والدم ومشتقات الحيوان غير المذكّى، وفصل خطوط الإنتاج أو تطهيرها عند الاشتراك.", "en": "In food manufacturing: products must be free of pork, intoxicating alcohol, blood and derivatives of unslaughtered animals, with production lines separated or cleansed when shared.", "ref": "OIC/SMIIC 1 (الغذاء الحلال)"}, {"kind": "condition", "ar": "في الصناعات الدوائية: التداوي بالمباح أصلٌ. ويُحال استعمال المواد المحرّمة غير المستحيلة إلى الهيئة، ويُقبل للضرورة عند انعدام البديل.", "en": "In pharmaceuticals: treatment with lawful substances is the rule. Use of untransformed prohibited substances is referred to the board and accepted only of necessity when no alternative exists.", "ref": "قاعدة «الضرورات تبيح المحظورات» مع تقديرها بقدرها"}, {"kind": "condition", "ar": "في مستحضرات التجميل: التحقق من مصدر الكولاجين والجيلاتين والدهون الحيوانية، وخلوّها من النجاسات.", "en": "In cosmetics: verify the source of collagen, gelatin and animal fats, and ensure freedom from impurities.", "ref": "OIC/SMIIC 4 (مستحضرات التجميل الحلال)"}, {"kind": "prohibition", "ar": "تصنيع الأسلحة أو المواد الكيميائية لبيعها لمن يُعلم أنه يستعملها في العدوان أو الإرهاب، وتصنيع أدوات القمار والتماثيل المعبودة.", "en": "Manufacturing weapons or chemicals for sale to those known to use them for aggression or terrorism, and making gambling devices or idols.", "ref": "النهي عن الإعانة على الإثم والعدوان"}, {"kind": "condition", "ar": "التصنيع للغير: يكيَّف استصناعًا أو إجارة أشخاص، ويُحدَّد فيه ملك المواد وضمانها وأجرة الصنعة.", "en": "Contract manufacturing is structured as istisna' or hiring of services, stating who owns the materials, who bears their risk, and the manufacturing fee.", "ref": "AAOIFI المعياران الشرعيان 11 (الاستصناع) و34 (إجارة الأشخاص)"}, {"kind": "mandatory", "ar": "الوسم والتغليف: بيان المكونات وبلد المنشأ وتاريخ الصلاحية بصدق، ومنع وضع علامة حلال دون شهادة معتمدة.", "en": "Labelling and packaging: state ingredients, country of origin and expiry truthfully, and never display a halal mark without accredited certification.", "ref": "حديث «من غشّنا فليس منّا»"}, {"kind": "condition", "ar": "المنتجات مزدوجة الاستعمال (كالكحول الصناعي والكيماويات): يجوز تصنيعها لمنافعها المباحة، مع ضوابط بيعٍ تمنع توجيهها إلى المحرّم.", "en": "Dual-use products (such as industrial alcohol and chemicals) may be made for lawful uses, with sales controls that prevent diversion to prohibited ends.", "ref": "قاعدة «الأمور بمقاصدها» وسدّ الذرائع"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "العدل في تسعير الخدمات الأساسية كالماء والكهرباء، ومنع الاحتكار واستغلال حاجة الناس.", "en": "Fair pricing of essential services such as water and electricity, without monopoly or exploiting people's need.", "ref": "حديث «لا يحتكر إلا خاطئ»", "strength": "nass"}, {"kind": "condition", "ar": "عقود التشغيل والصيانة والامتياز (كالبناء والتشغيل والتحويل): تُكيَّف إجارةً أو استصناعًا أو امتيازًا، مع بيان المدة والعوض وتوزيع المخاطر، دون عائدٍ مضمون على التمويل.", "en": "Operation, maintenance and concession contracts (such as build-operate-transfer) are structured as ijarah, istisna' or concession, with a clear term, consideration and risk allocation, and no guaranteed return on financing.", "ref": "AAOIFI المعايير الشرعية 9 و11 و22", "strength": "ijtihad"}, {"kind": "condition", "ar": "المياه المعالَجة: يُعمل بقرارات المجامع في طهارة المياه المعالجة إذا زال التغيّر، ويُفصح عن الاستعمالات المسموح بها.", "en": "Treated water: follow fiqh academy resolutions on the purity of treated water once its change has gone, and disclose permitted uses.", "ref": "قرارات مجمع الفقه الإسلامي في المياه المعالجة", "strength": "ijma"}, {"kind": "mandatory", "ar": "إدارة النفايات الخطرة والطبية بما يمنع الضرر بالناس والتربة والمياه، والإفصاح عن الحوادث البيئية.", "en": "Manage hazardous and medical waste so as to prevent harm to people, soil and water, and disclose environmental incidents.", "ref": "قاعدة «لا ضرر ولا ضرار»", "strength": "ijtihad"}, {"kind": "condition", "ar": "إعادة التدوير وبيع المخلّفات: جواز بيع ما فيه منفعة مباحة، واستثناء الأعيان النجسة التي لا ينتفع بها إلا في محرّم.", "en": "Recycling and selling waste: items with a lawful use may be sold, excluding impure items usable only for prohibited ends.", "ref": "قاعدة «ما جاز الانتفاع به جاز بيعه»", "strength": "ijtihad"}, {"kind": "condition", "ar": "أرصدة الكربون وشهادات الطاقة: تُحال إلى الهيئة لتكييفها (حق مالي أو تعهّد) قبل تداولها.", "en": "Carbon credits and energy certificates are referred to the board for characterisation (financial right or undertaking) before trading.", "ref": "نازلة معاصرة", "strength": "khilaf"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$E$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "العدل في تسعير الخدمات الأساسية كالماء والكهرباء، ومنع الاحتكار واستغلال حاجة الناس.", "en": "Fair pricing of essential services such as water and electricity, without monopoly or exploiting people's need.", "ref": "حديث «لا يحتكر إلا خاطئ»"}, {"kind": "condition", "ar": "عقود التشغيل والصيانة والامتياز (كالبناء والتشغيل والتحويل): تُكيَّف إجارةً أو استصناعًا أو امتيازًا، مع بيان المدة والعوض وتوزيع المخاطر، دون عائدٍ مضمون على التمويل.", "en": "Operation, maintenance and concession contracts (such as build-operate-transfer) are structured as ijarah, istisna' or concession, with a clear term, consideration and risk allocation, and no guaranteed return on financing.", "ref": "AAOIFI المعايير الشرعية 9 و11 و22"}, {"kind": "condition", "ar": "المياه المعالَجة: يُعمل بقرارات المجامع في طهارة المياه المعالجة إذا زال التغيّر، ويُفصح عن الاستعمالات المسموح بها.", "en": "Treated water: follow fiqh academy resolutions on the purity of treated water once its change has gone, and disclose permitted uses.", "ref": "قرارات مجمع الفقه الإسلامي في المياه المعالجة"}, {"kind": "mandatory", "ar": "إدارة النفايات الخطرة والطبية بما يمنع الضرر بالناس والتربة والمياه، والإفصاح عن الحوادث البيئية.", "en": "Manage hazardous and medical waste so as to prevent harm to people, soil and water, and disclose environmental incidents.", "ref": "قاعدة «لا ضرر ولا ضرار»"}, {"kind": "condition", "ar": "إعادة التدوير وبيع المخلّفات: جواز بيع ما فيه منفعة مباحة، واستثناء الأعيان النجسة التي لا ينتفع بها إلا في محرّم.", "en": "Recycling and selling waste: items with a lawful use may be sold, excluding impure items usable only for prohibited ends.", "ref": "قاعدة «ما جاز الانتفاع به جاز بيعه»"}, {"kind": "condition", "ar": "أرصدة الكربون وشهادات الطاقة: تُحال إلى الهيئة لتكييفها (حق مالي أو تعهّد) قبل تداولها.", "en": "Carbon credits and energy certificates are referred to the board for characterisation (financial right or undertaking) before trading.", "ref": "نازلة معاصرة"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "بيع الوحدات على الخارطة: يُكيَّف استصناعًا بمواصفات منضبطة وجدول تسليم، مع حماية دفعات المشترين (حساب ضمان).", "en": "Off-plan sales are structured as istisna' with precise specifications and a delivery schedule, protecting buyers' payments (escrow).", "ref": "AAOIFI المعيار الشرعي 11 (الاستصناع)", "strength": "ijma"}, {"kind": "condition", "ar": "التمويل العقاري بصيغ المرابحة أو الإجارة المنتهية بالتمليك أو المشاركة المتناقصة، مع تملّك الممول للعقار أو حصته قبل بيعه أو تأجيره.", "en": "Property finance through murabahah, ijarah ending in ownership or diminishing musharakah, with the financier owning the property or its share before selling or leasing it.", "ref": "AAOIFI المعايير الشرعية 8 و9 و12", "strength": "ijma"}, {"kind": "mandatory", "ar": "عقود الإيجار: تحديد المدة والأجرة والعين، وتحمّل المالك للصيانة الأساسية وتأمين العين. ويجوز ربط الأجرة بمؤشرٍ في الفترات اللاحقة إذا حُدِّدت أجرة كل فترة عند بدئها.", "en": "Leases: define the term, rent and property; the owner bears major maintenance and insurance. Rent may track an index in later periods if each period's rent is fixed at its start.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "تأجير العقار أو بيعه لنشاطٍ محرّمٍ ظاهرٍ مع العلم (كالملاهي المحرمة ومحلات الخمور)، وإدراج غرامات تأخير تعود للمؤجر ربحًا.", "en": "Leasing or selling property for a clearly prohibited activity with knowledge (such as bars or illicit venues), and late-payment penalties retained by the lessor as profit.", "ref": "النهي عن الإعانة على الإثم؛ AAOIFI المعيار الشرعي 3", "strength": "ijtihad"}, {"kind": "condition", "ar": "الوساطة العقارية: عمولة معلومة على عملٍ منضبط، والصدق في وصف العقار وعيوبه، ومنع النجش في المزادات.", "en": "Real estate brokerage: a known commission for defined work, truthful description of the property and its defects, and no bid rigging in auctions.", "ref": "النهي عن النجش", "strength": "nass"}, {"kind": "mandatory", "ar": "حقوق الجوار والتخطيط: الالتزام بأنظمة البناء، وعدم الإضرار بالجار في الضوء والهواء والارتفاق.", "en": "Neighbours' rights and planning: comply with building regulations and do not harm neighbours' light, air or easements.", "ref": "حديث «لا ضرر ولا ضرار»", "strength": "ijtihad"}, {"kind": "condition", "ar": "الصناديق والصكوك العقارية: أن تمثّل ملكيةً حقيقية في العقار أو منافعه، وألا يُضمن رأس المال أو عائدٌ ثابت.", "en": "Real estate funds and sukuk must represent genuine ownership of property or its usufruct, with no guaranteed capital or fixed return.", "ref": "AAOIFI المعيار الشرعي 17 (صكوك الاستثمار)", "strength": "ijma"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$F$v$ AND requirements = $v$[{"kind": "condition", "ar": "بيع الوحدات على الخارطة: يُكيَّف استصناعًا بمواصفات منضبطة وجدول تسليم، مع حماية دفعات المشترين (حساب ضمان).", "en": "Off-plan sales are structured as istisna' with precise specifications and a delivery schedule, protecting buyers' payments (escrow).", "ref": "AAOIFI المعيار الشرعي 11 (الاستصناع)"}, {"kind": "condition", "ar": "التمويل العقاري بصيغ المرابحة أو الإجارة المنتهية بالتمليك أو المشاركة المتناقصة، مع تملّك الممول للعقار أو حصته قبل بيعه أو تأجيره.", "en": "Property finance through murabahah, ijarah ending in ownership or diminishing musharakah, with the financier owning the property or its share before selling or leasing it.", "ref": "AAOIFI المعايير الشرعية 8 و9 و12"}, {"kind": "mandatory", "ar": "عقود الإيجار: تحديد المدة والأجرة والعين، وتحمّل المالك للصيانة الأساسية وتأمين العين. ويجوز ربط الأجرة بمؤشرٍ في الفترات اللاحقة إذا حُدِّدت أجرة كل فترة عند بدئها.", "en": "Leases: define the term, rent and property; the owner bears major maintenance and insurance. Rent may track an index in later periods if each period's rent is fixed at its start.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)"}, {"kind": "prohibition", "ar": "تأجير العقار أو بيعه لنشاطٍ محرّمٍ ظاهرٍ مع العلم (كالملاهي المحرمة ومحلات الخمور)، وإدراج غرامات تأخير تعود للمؤجر ربحًا.", "en": "Leasing or selling property for a clearly prohibited activity with knowledge (such as bars or illicit venues), and late-payment penalties retained by the lessor as profit.", "ref": "النهي عن الإعانة على الإثم؛ AAOIFI المعيار الشرعي 3"}, {"kind": "condition", "ar": "الوساطة العقارية: عمولة معلومة على عملٍ منضبط، والصدق في وصف العقار وعيوبه، ومنع النجش في المزادات.", "en": "Real estate brokerage: a known commission for defined work, truthful description of the property and its defects, and no bid rigging in auctions.", "ref": "النهي عن النجش"}, {"kind": "mandatory", "ar": "حقوق الجوار والتخطيط: الالتزام بأنظمة البناء، وعدم الإضرار بالجار في الضوء والهواء والارتفاق.", "en": "Neighbours' rights and planning: comply with building regulations and do not harm neighbours' light, air or easements.", "ref": "حديث «لا ضرر ولا ضرار»"}, {"kind": "condition", "ar": "الصناديق والصكوك العقارية: أن تمثّل ملكيةً حقيقية في العقار أو منافعه، وألا يُضمن رأس المال أو عائدٌ ثابت.", "en": "Real estate funds and sukuk must represent genuine ownership of property or its usufruct, with no guaranteed capital or fixed return.", "ref": "AAOIFI المعيار الشرعي 17 (صكوك الاستثمار)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "الاتجار في الخمور ولحم الخنزير والمخدرات وأدوات القمار والمواد الإباحية، أو تخصيص جزء من المتجر لها.", "en": "Trading in alcohol, pork, drugs, gambling equipment or pornographic material, or dedicating part of a store to them.", "ref": "حديث «إن الله إذا حرّم شيئًا حرّم ثمنه»", "strength": "nass"}, {"kind": "mandatory", "ar": "القبض قبل البيع فيما يُشترط فيه القبض، ويتحقق القبض الحكمي بالتمكين والتخلية أو القيد في المستودع باسم البائع.", "en": "Take possession before resale where required; constructive possession occurs through control and release, or registration in the seller's name at the warehouse.", "ref": "AAOIFI المعيار الشرعي 18 (القبض)", "strength": "nass"}, {"kind": "condition", "ar": "البيع بالتقسيط: جواز زيادة الثمن الآجل على الحال عند العقد، ومنع الزيادة عند التأخر في السداد، وما يُلتزم به من تبرّع عند المطل يُصرف في الخير.", "en": "Instalment sales: a deferred price may exceed the cash price if agreed at contract; no increase for late payment, and any charitable undertaking on default goes to charity.", "ref": "AAOIFI المعيار الشرعي 3 (المدين المماطل)", "strength": "ijma"}, {"kind": "condition", "ar": "التجارة الإلكترونية: وصف المنتج وصفًا يرفع الجهالة، وإعمال خيار الرؤية أو الإرجاع، وبيان رسوم الشحن والضرائب قبل إتمام الشراء.", "en": "E-commerce: describe products so as to remove uncertainty, honour the option to inspect or return, and disclose shipping and taxes before checkout.", "ref": "النهي عن بيع الغرر", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "المسابقات والسحوبات التي يدفع فيها المشارك مقابلًا للدخول فيها، أو التي يُرفع فيها سعر السلعة من أجل الجائزة.", "en": "Prize draws that require paying to enter, or that raise a product's price because of the prize.", "ref": "تحريم الميسر", "strength": "ijma"}, {"kind": "condition", "ar": "الوكالات التجارية والتوزيع الحصري: تكيَّف وكالة بأجر أو بيعًا، مع بيان حقوق الحصرية وأجرها بما لا يفضي إلى الاحتكار الضار.", "en": "Commercial agencies and exclusive distribution are structured as paid agency or sale, with exclusivity rights and fees stated so as not to cause harmful monopoly.", "ref": "AAOIFI المعيار الشرعي 23 (الوكالة)", "strength": "ijtihad"}, {"kind": "condition", "ar": "بطاقات الولاء والخصومات: جوازها ما لم تكن مقابل رسومٍ تفضي إلى غرر أو قمار.", "en": "Loyalty cards and discounts are permitted unless they involve fees that lead to gharar or gambling.", "ref": "AAOIFI المعيار الشرعي 2 (بطاقات الحسم والائتمان)", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$G$v$ AND requirements = $v$[{"kind": "prohibition", "ar": "الاتجار في الخمور ولحم الخنزير والمخدرات وأدوات القمار والمواد الإباحية، أو تخصيص جزء من المتجر لها.", "en": "Trading in alcohol, pork, drugs, gambling equipment or pornographic material, or dedicating part of a store to them.", "ref": "حديث «إن الله إذا حرّم شيئًا حرّم ثمنه»"}, {"kind": "mandatory", "ar": "القبض قبل البيع فيما يُشترط فيه القبض، ويتحقق القبض الحكمي بالتمكين والتخلية أو القيد في المستودع باسم البائع.", "en": "Take possession before resale where required; constructive possession occurs through control and release, or registration in the seller's name at the warehouse.", "ref": "AAOIFI المعيار الشرعي 18 (القبض)"}, {"kind": "condition", "ar": "البيع بالتقسيط: جواز زيادة الثمن الآجل على الحال عند العقد، ومنع الزيادة عند التأخر في السداد، وما يُلتزم به من تبرّع عند المطل يُصرف في الخير.", "en": "Instalment sales: a deferred price may exceed the cash price if agreed at contract; no increase for late payment, and any charitable undertaking on default goes to charity.", "ref": "AAOIFI المعيار الشرعي 3 (المدين المماطل)"}, {"kind": "condition", "ar": "التجارة الإلكترونية: وصف المنتج وصفًا يرفع الجهالة، وإعمال خيار الرؤية أو الإرجاع، وبيان رسوم الشحن والضرائب قبل إتمام الشراء.", "en": "E-commerce: describe products so as to remove uncertainty, honour the option to inspect or return, and disclose shipping and taxes before checkout.", "ref": "النهي عن بيع الغرر"}, {"kind": "prohibition", "ar": "المسابقات والسحوبات التي يدفع فيها المشارك مقابلًا للدخول فيها، أو التي يُرفع فيها سعر السلعة من أجل الجائزة.", "en": "Prize draws that require paying to enter, or that raise a product's price because of the prize.", "ref": "تحريم الميسر"}, {"kind": "condition", "ar": "الوكالات التجارية والتوزيع الحصري: تكيَّف وكالة بأجر أو بيعًا، مع بيان حقوق الحصرية وأجرها بما لا يفضي إلى الاحتكار الضار.", "en": "Commercial agencies and exclusive distribution are structured as paid agency or sale, with exclusivity rights and fees stated so as not to cause harmful monopoly.", "ref": "AAOIFI المعيار الشرعي 23 (الوكالة)"}, {"kind": "condition", "ar": "بطاقات الولاء والخصومات: جوازها ما لم تكن مقابل رسومٍ تفضي إلى غرر أو قمار.", "en": "Loyalty cards and discounts are permitted unless they involve fees that lead to gharar or gambling.", "ref": "AAOIFI المعيار الشرعي 2 (بطاقات الحسم والائتمان)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "عقد النقل إجارةٌ على عمل: تحديد محل النقل والمسافة والمدة والأجرة، والناقل أجيرٌ مشترك يضمن ما تلف بتعدّيه أو تفريطه.", "en": "Carriage is a hire of services: specify the goods, route, time and fare; the carrier as a common hire is liable for loss caused by transgression or negligence.", "ref": "AAOIFI المعيار الشرعي 34 (إجارة الأشخاص)", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "نقل الخمور والمخدرات والمواد المحرمة أو تخزينها مع العلم بها، إلا ما كان لأغراضٍ مباحة ثابتة.", "en": "Knowingly carrying or storing alcohol, drugs or other prohibited goods, except for established lawful purposes.", "ref": "حديث لعن حامل الخمر والمحمولة إليه", "strength": "nass"}, {"kind": "condition", "ar": "تأجير المركبات والسفن والطائرات: تشغيليًّا أو منتهيًا بالتمليك، مع تحمّل المالك تبعة الهلاك والصيانة الأساسية.", "en": "Leasing vehicles, ships and aircraft, operationally or ending in ownership, with the owner bearing the risk of loss and major maintenance.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)", "strength": "ijma"}, {"kind": "mandatory", "ar": "التخزين أمانة: يضمن المخزّن ما تلف بتعدّيه أو تقصيره، ولا يجوز التصرف في البضائع المخزّنة بغير إذن.", "en": "Storage is a trust: the warehouse is liable for loss caused by transgression or negligence, and may not dispose of stored goods without permission.", "ref": "أحكام الوديعة", "strength": "ijma"}, {"kind": "condition", "ar": "التأمين على الشحنات بالتكافل حيث يتاح، ويُفصح عن التأمين التجاري الإلزامي.", "en": "Insure cargo through takaful where available, and disclose any mandatory conventional insurance.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "السلامة على الطرق والموانئ والمطارات، والوفاء بالمواعيد، وعدم تحميل العاملين فوق طاقتهم.", "en": "Safety on roads, ports and airports, keeping to schedules, and not overburdening workers.", "ref": "قاعدة «لا ضرر ولا ضرار»", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$H$v$ AND requirements = $v$[{"kind": "condition", "ar": "عقد النقل إجارةٌ على عمل: تحديد محل النقل والمسافة والمدة والأجرة، والناقل أجيرٌ مشترك يضمن ما تلف بتعدّيه أو تفريطه.", "en": "Carriage is a hire of services: specify the goods, route, time and fare; the carrier as a common hire is liable for loss caused by transgression or negligence.", "ref": "AAOIFI المعيار الشرعي 34 (إجارة الأشخاص)"}, {"kind": "prohibition", "ar": "نقل الخمور والمخدرات والمواد المحرمة أو تخزينها مع العلم بها، إلا ما كان لأغراضٍ مباحة ثابتة.", "en": "Knowingly carrying or storing alcohol, drugs or other prohibited goods, except for established lawful purposes.", "ref": "حديث لعن حامل الخمر والمحمولة إليه"}, {"kind": "condition", "ar": "تأجير المركبات والسفن والطائرات: تشغيليًّا أو منتهيًا بالتمليك، مع تحمّل المالك تبعة الهلاك والصيانة الأساسية.", "en": "Leasing vehicles, ships and aircraft, operationally or ending in ownership, with the owner bearing the risk of loss and major maintenance.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)"}, {"kind": "mandatory", "ar": "التخزين أمانة: يضمن المخزّن ما تلف بتعدّيه أو تقصيره، ولا يجوز التصرف في البضائع المخزّنة بغير إذن.", "en": "Storage is a trust: the warehouse is liable for loss caused by transgression or negligence, and may not dispose of stored goods without permission.", "ref": "أحكام الوديعة"}, {"kind": "condition", "ar": "التأمين على الشحنات بالتكافل حيث يتاح، ويُفصح عن التأمين التجاري الإلزامي.", "en": "Insure cargo through takaful where available, and disclose any mandatory conventional insurance.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)"}, {"kind": "mandatory", "ar": "السلامة على الطرق والموانئ والمطارات، والوفاء بالمواعيد، وعدم تحميل العاملين فوق طاقتهم.", "en": "Safety on roads, ports and airports, keeping to schedules, and not overburdening workers.", "ref": "قاعدة «لا ضرر ولا ضرار»"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "الإقراض والاقتراض بفائدة، وبيع الدين بالدين، وخصم الأوراق التجارية، والتورّق المنظّم الذي لا حقيقة للسلعة فيه.", "en": "Lending or borrowing at interest, selling debt for debt, discounting commercial paper, and organised tawarruq with no real commodity.", "ref": "AAOIFI المعيار الشرعي 30 (التورق)", "strength": "nass"}, {"kind": "mandatory", "ar": "الودائع: الحسابات الجارية قروضٌ مضمونة بلا عائد، وحسابات الاستثمار مضاربةٌ أو وكالة بالاستثمار لا يُضمن فيها رأس المال ولا الربح.", "en": "Deposits: current accounts are guaranteed loans without return; investment accounts are mudarabah or investment agency with no guaranteed capital or profit.", "ref": "AAOIFI المعياران الشرعيان 13 (المضاربة) و19 (القرض)", "strength": "ijma"}, {"kind": "mandatory", "ar": "المرابحة: تملّك المؤسسة للسلعة وقبضها قبل بيعها، والوعد غير الملزم للطرفين معًا بما يرقى إلى عقدٍ قبل التملّك.", "en": "Murabahah: the institution owns and possesses the goods before selling them, and there is no mutually binding promise that amounts to a sale before ownership.", "ref": "AAOIFI المعيار الشرعي 8 (المرابحة)", "strength": "ijma"}, {"kind": "condition", "ar": "الاستثمار في الأسهم: الالتزام بحدود الفرز (الدين الربوي ≤30%، والودائع الربوية ≤30%، والدخل غير المباح ≤5%)، وتطهير العائد.", "en": "Equity investment: apply the screens (interest-bearing debt ≤30%, interest-bearing deposits ≤30%, non-permissible income ≤5%) and purify returns.", "ref": "AAOIFI المعيار الشرعي 21 (الأوراق المالية)", "strength": "ijtihad"}, {"kind": "condition", "ar": "الصكوك: تمثيل ملكية حقيقية في موجودات، وعدم ضمان المدير لرأس المال أو العائد، والتزامه بالشراء بالقيمة السوقية لا الاسمية.", "en": "Sukuk must represent real ownership of assets, with no manager guarantee of capital or return, and any purchase undertaking at market value, not par.", "ref": "AAOIFI المعيار الشرعي 17 (صكوك الاستثمار)", "strength": "ijma"}, {"kind": "mandatory", "ar": "التأمين: التكافل القائم على التبرع ومحفظة مستقلة للمشتركين عن مال الشركة المديرة، وتوزيع الفائض وفق اللوائح.", "en": "Insurance: donation-based takaful with a participants' fund separate from the operator's, and surplus distributed under the rules.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)", "strength": "ijma"}, {"kind": "mandatory", "ar": "الرقابة الشرعية: هيئة رقابة شرعية مستقلة، وتدقيق شرعي داخلي وخارجي، وإفصاح سنوي عن الالتزام.", "en": "Shariah oversight: an independent Shariah supervisory board, internal and external Shariah audit, and annual compliance disclosure.", "ref": "معايير الحوكمة الصادرة عن أيوفي", "strength": "ijtihad"}, {"kind": "condition", "ar": "الأصول الرقمية في وضع الإحالة. والمشتقات والعقود المستقبلية والخيارات التقليدية ممنوعة ما لم تعتمد الهيئة بديلًا منضبطًا.", "en": "Digital assets remain under referral. Conventional derivatives, futures and options are not permitted unless the board approves a compliant alternative.", "ref": "قرار مجمع الفقه 237؛ AAOIFI المعيار الشرعي 20", "strength": "khilaf"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$K$v$ AND requirements = $v$[{"kind": "prohibition", "ar": "الإقراض والاقتراض بفائدة، وبيع الدين بالدين، وخصم الأوراق التجارية، والتورّق المنظّم الذي لا حقيقة للسلعة فيه.", "en": "Lending or borrowing at interest, selling debt for debt, discounting commercial paper, and organised tawarruq with no real commodity.", "ref": "AAOIFI المعيار الشرعي 30 (التورق)"}, {"kind": "mandatory", "ar": "الودائع: الحسابات الجارية قروضٌ مضمونة بلا عائد، وحسابات الاستثمار مضاربةٌ أو وكالة بالاستثمار لا يُضمن فيها رأس المال ولا الربح.", "en": "Deposits: current accounts are guaranteed loans without return; investment accounts are mudarabah or investment agency with no guaranteed capital or profit.", "ref": "AAOIFI المعياران الشرعيان 13 (المضاربة) و19 (القرض)"}, {"kind": "mandatory", "ar": "المرابحة: تملّك المؤسسة للسلعة وقبضها قبل بيعها، والوعد غير الملزم للطرفين معًا بما يرقى إلى عقدٍ قبل التملّك.", "en": "Murabahah: the institution owns and possesses the goods before selling them, and there is no mutually binding promise that amounts to a sale before ownership.", "ref": "AAOIFI المعيار الشرعي 8 (المرابحة)"}, {"kind": "condition", "ar": "الاستثمار في الأسهم: الالتزام بحدود الفرز (الدين الربوي ≤30%، والودائع الربوية ≤30%، والدخل غير المباح ≤5%)، وتطهير العائد.", "en": "Equity investment: apply the screens (interest-bearing debt ≤30%, interest-bearing deposits ≤30%, non-permissible income ≤5%) and purify returns.", "ref": "AAOIFI المعيار الشرعي 21 (الأوراق المالية)"}, {"kind": "condition", "ar": "الصكوك: تمثيل ملكية حقيقية في موجودات، وعدم ضمان المدير لرأس المال أو العائد، والتزامه بالشراء بالقيمة السوقية لا الاسمية.", "en": "Sukuk must represent real ownership of assets, with no manager guarantee of capital or return, and any purchase undertaking at market value, not par.", "ref": "AAOIFI المعيار الشرعي 17 (صكوك الاستثمار)"}, {"kind": "mandatory", "ar": "التأمين: التكافل القائم على التبرع ومحفظة مستقلة للمشتركين عن مال الشركة المديرة، وتوزيع الفائض وفق اللوائح.", "en": "Insurance: donation-based takaful with a participants' fund separate from the operator's, and surplus distributed under the rules.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)"}, {"kind": "mandatory", "ar": "الرقابة الشرعية: هيئة رقابة شرعية مستقلة، وتدقيق شرعي داخلي وخارجي، وإفصاح سنوي عن الالتزام.", "en": "Shariah oversight: an independent Shariah supervisory board, internal and external Shariah audit, and annual compliance disclosure.", "ref": "معايير الحوكمة الصادرة عن أيوفي"}, {"kind": "condition", "ar": "الأصول الرقمية في وضع الإحالة. والمشتقات والعقود المستقبلية والخيارات التقليدية ممنوعة ما لم تعتمد الهيئة بديلًا منضبطًا.", "en": "Digital assets remain under referral. Conventional derivatives, futures and options are not permitted unless the board approves a compliant alternative.", "ref": "قرار مجمع الفقه 237؛ AAOIFI المعيار الشرعي 20"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "المنصات الوسيطة: تكيَّف عمولتها أجرة سمسرة أو وكالة، وتتحمّل مسؤولية التحقق من مشروعية ما يُعرض عليها بحسب الوسع.", "en": "Marketplace platforms: commissions are brokerage or agency fees, and the platform verifies, as far as feasible, that listed offerings are lawful.", "ref": "AAOIFI المعيار الشرعي 23 (الوكالة)", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "صناديق الغنائم المدفوعة (Loot Boxes) وآليات الرهان داخل الألعاب التي يدفع فيها المستخدم مقابل نتيجةٍ مجهولة.", "en": "Paid loot boxes and in-game betting mechanics where users pay for an unknown outcome.", "ref": "تحريم الميسر والغرر", "strength": "ijtihad"}, {"kind": "condition", "ar": "العملات والنقاط داخل التطبيقات: تُعامل حقًّا في منفعة، ولا تُسترد نقدًا بزيادة، ولا تُستعمل للقمار.", "en": "In-app currencies and points are treated as a right to a service, not redeemable for more cash, and never used for gambling.", "ref": "أحكام الصرف والربا", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "حماية البيانات: الحدّ الأدنى من الجمع، والتشفير، والإفصاح عن المشاركة مع الغير، وحق المستخدم في الحذف.", "en": "Data protection: minimal collection, encryption, disclosure of third-party sharing, and the user's right to deletion.", "ref": "أحكام الأمانة وحرمة التجسّس", "strength": "ijtihad"}, {"kind": "condition", "ar": "نماذج الإيراد الإعلاني: منع الإعلانات المحرّمة، وتطهير ما يرد منها بغير قصد.", "en": "Advertising revenue models: block prohibited adverts and purify income received from them unintentionally.", "ref": "AAOIFI المعيار الشرعي 21 (التطهير)", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "الملكية الفكرية: احترام تراخيص البرمجيات مفتوحة المصدر وشروطها، ومنع استخدام البرمجيات المقرصنة.", "en": "Intellectual property: respect open-source licences and their terms, and do not use pirated software.", "ref": "قرار مجمع الفقه الإسلامي الدولي بشأن الحقوق المعنوية", "strength": "ijma"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$J$v$ AND requirements = $v$[{"kind": "condition", "ar": "المنصات الوسيطة: تكيَّف عمولتها أجرة سمسرة أو وكالة، وتتحمّل مسؤولية التحقق من مشروعية ما يُعرض عليها بحسب الوسع.", "en": "Marketplace platforms: commissions are brokerage or agency fees, and the platform verifies, as far as feasible, that listed offerings are lawful.", "ref": "AAOIFI المعيار الشرعي 23 (الوكالة)"}, {"kind": "prohibition", "ar": "صناديق الغنائم المدفوعة (Loot Boxes) وآليات الرهان داخل الألعاب التي يدفع فيها المستخدم مقابل نتيجةٍ مجهولة.", "en": "Paid loot boxes and in-game betting mechanics where users pay for an unknown outcome.", "ref": "تحريم الميسر والغرر"}, {"kind": "condition", "ar": "العملات والنقاط داخل التطبيقات: تُعامل حقًّا في منفعة، ولا تُسترد نقدًا بزيادة، ولا تُستعمل للقمار.", "en": "In-app currencies and points are treated as a right to a service, not redeemable for more cash, and never used for gambling.", "ref": "أحكام الصرف والربا"}, {"kind": "mandatory", "ar": "حماية البيانات: الحدّ الأدنى من الجمع، والتشفير، والإفصاح عن المشاركة مع الغير، وحق المستخدم في الحذف.", "en": "Data protection: minimal collection, encryption, disclosure of third-party sharing, and the user's right to deletion.", "ref": "أحكام الأمانة وحرمة التجسّس"}, {"kind": "condition", "ar": "نماذج الإيراد الإعلاني: منع الإعلانات المحرّمة، وتطهير ما يرد منها بغير قصد.", "en": "Advertising revenue models: block prohibited adverts and purify income received from them unintentionally.", "ref": "AAOIFI المعيار الشرعي 21 (التطهير)"}, {"kind": "mandatory", "ar": "الملكية الفكرية: احترام تراخيص البرمجيات مفتوحة المصدر وشروطها، ومنع استخدام البرمجيات المقرصنة.", "en": "Intellectual property: respect open-source licences and their terms, and do not use pirated software.", "ref": "قرار مجمع الفقه الإسلامي الدولي بشأن الحقوق المعنوية"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "حفظ النفس مقدَّم: تقديم الإسعاف والحالات الطارئة دون اشتراط الدفع المسبق.", "en": "Preserving life comes first: provide emergency care without requiring advance payment.", "ref": "مقصد حفظ النفس", "strength": "ijma"}, {"kind": "mandatory", "ar": "الستر وحفظ العورات: تقديم الفحص من نفس الجنس حيث أمكن، وحضور المَحرم أو المرافق عند الحاجة.", "en": "Modesty: same-gender examination where possible, and a chaperone or relative present when needed.", "ref": "قاعدة «ما أُبيح للضرورة يُقدَّر بقدرها»", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "الإجهاض لغير عذرٍ شرعي معتبر، والتلقيح الصناعي بغير ماء الزوجين، والاستنساخ البشري، وبيع الأعضاء.", "en": "Abortion without a recognised Shariah justification, assisted reproduction using gametes from outside the marriage, human cloning, and selling organs.", "ref": "قرارات مجمع الفقه الإسلامي الدولي في أطفال الأنابيب والاستنساخ ونقل الأعضاء", "strength": "ijma"}, {"kind": "condition", "ar": "الأدوية والمستحضرات: التحقق من حِلّ المكونات، ويُحال ما فيه مواد محرّمة غير مستحيلة إلى الهيئة، ويُقبل للضرورة عند انعدام البديل.", "en": "Medicines: verify lawful ingredients; products with untransformed prohibited substances are referred to the board and accepted of necessity without alternatives.", "ref": "معايير SMIIC للدواء الحلال", "strength": "khilaf"}, {"kind": "mandatory", "ar": "خصوصية المريض وسرّية سجلاته، وعدم إفشائها إلا بإذنه أو لمصلحة معتبرة ينص عليها النظام.", "en": "Patient privacy and confidentiality of records, disclosed only with consent or for a recognised legal interest.", "ref": "أحكام حفظ السرّ", "strength": "ijtihad"}, {"kind": "condition", "ar": "التأمين الصحي بالتكافل حيث يتاح، والتعاقد مع المستشفيات بأسعار معلومة.", "en": "Health insurance through takaful where available, and contracts with hospitals at known prices.", "ref": "AAOIFI المعيار الشرعي 26", "strength": "ijtihad"}, {"kind": "condition", "ar": "الأبحاث الجينية والتجارب السريرية: الموافقة المستنيرة، وأخلاقيات البحث، وعدم العبث بالخلق لغير غرضٍ علاجي معتبر.", "en": "Genetic research and clinical trials: informed consent, research ethics, and no alteration of creation beyond recognised therapeutic purposes.", "ref": "قرارات مجمع الفقه الإسلامي في الهندسة الوراثية", "strength": "ijma"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$Q$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "حفظ النفس مقدَّم: تقديم الإسعاف والحالات الطارئة دون اشتراط الدفع المسبق.", "en": "Preserving life comes first: provide emergency care without requiring advance payment.", "ref": "مقصد حفظ النفس"}, {"kind": "mandatory", "ar": "الستر وحفظ العورات: تقديم الفحص من نفس الجنس حيث أمكن، وحضور المَحرم أو المرافق عند الحاجة.", "en": "Modesty: same-gender examination where possible, and a chaperone or relative present when needed.", "ref": "قاعدة «ما أُبيح للضرورة يُقدَّر بقدرها»"}, {"kind": "prohibition", "ar": "الإجهاض لغير عذرٍ شرعي معتبر، والتلقيح الصناعي بغير ماء الزوجين، والاستنساخ البشري، وبيع الأعضاء.", "en": "Abortion without a recognised Shariah justification, assisted reproduction using gametes from outside the marriage, human cloning, and selling organs.", "ref": "قرارات مجمع الفقه الإسلامي الدولي في أطفال الأنابيب والاستنساخ ونقل الأعضاء"}, {"kind": "condition", "ar": "الأدوية والمستحضرات: التحقق من حِلّ المكونات، ويُحال ما فيه مواد محرّمة غير مستحيلة إلى الهيئة، ويُقبل للضرورة عند انعدام البديل.", "en": "Medicines: verify lawful ingredients; products with untransformed prohibited substances are referred to the board and accepted of necessity without alternatives.", "ref": "معايير SMIIC للدواء الحلال"}, {"kind": "mandatory", "ar": "خصوصية المريض وسرّية سجلاته، وعدم إفشائها إلا بإذنه أو لمصلحة معتبرة ينص عليها النظام.", "en": "Patient privacy and confidentiality of records, disclosed only with consent or for a recognised legal interest.", "ref": "أحكام حفظ السرّ"}, {"kind": "condition", "ar": "التأمين الصحي بالتكافل حيث يتاح، والتعاقد مع المستشفيات بأسعار معلومة.", "en": "Health insurance through takaful where available, and contracts with hospitals at known prices.", "ref": "AAOIFI المعيار الشرعي 26"}, {"kind": "condition", "ar": "الأبحاث الجينية والتجارب السريرية: الموافقة المستنيرة، وأخلاقيات البحث، وعدم العبث بالخلق لغير غرضٍ علاجي معتبر.", "en": "Genetic research and clinical trials: informed consent, research ethics, and no alteration of creation beyond recognised therapeutic purposes.", "ref": "قرارات مجمع الفقه الإسلامي في الهندسة الوراثية"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "أخذ الأجر على التعليم جائز، ويكيَّف عقد إجارةٍ على منفعة معلومة المدة والمحتوى والرسوم.", "en": "Charging for teaching is permitted, structured as a lease of services with a known term, content and fee.", "ref": "حديث «إن أحقّ ما أخذتم عليه أجرًا كتاب الله»", "strength": "ijma"}, {"kind": "mandatory", "ar": "مراجعة المناهج والمحتوى من حيث موافقتها للشريعة، واجتناب ما يدعو إلى محرّم أو يطعن في الثوابت.", "en": "Review curricula and content for consistency with Shariah, avoiding material that promotes the prohibited or attacks core beliefs.", "ref": "مقصد حفظ الدين والعقل", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "القروض الدراسية بفائدة، وتقديم الشهادات دون تحصيل حقيقي، وبيع الأبحاث الجاهزة للطلاب.", "en": "Interest-bearing student loans, awarding certificates without real attainment, and selling ready-made papers to students.", "ref": "تحريم الربا والغش", "strength": "nass"}, {"kind": "mandatory", "ar": "الأمانة العلمية: نسبة الأقوال إلى أصحابها، ومنع الانتحال، وحفظ حقوق المؤلفين.", "en": "Academic integrity: attribute ideas to their authors, prevent plagiarism, and protect authors' rights.", "ref": "قرار مجمع الفقه الإسلامي بشأن الحقوق المعنوية", "strength": "ijma"}, {"kind": "condition", "ar": "الأوقاف التعليمية والمنح: الالتزام بشرط الواقف، والشفافية في معايير المنح وصرفها.", "en": "Educational endowments and scholarships: follow the endower's conditions, with transparent award criteria and spending.", "ref": "AAOIFI المعيار الشرعي 33 (الوقف)", "strength": "ijtihad"}, {"kind": "condition", "ar": "التعليم الرقمي: وضوح مدة الوصول والمحتوى وسياسة الاسترداد، ومراعاة الضوابط في التعليم المختلط وفق أنظمة الدولة وتوجيه الهيئة.", "en": "Digital education: clear access period, content and refund policy, and observing mixed-gender guidance per national rules and the board's direction.", "ref": "النهي عن الغرر", "strength": "ijtihad"}]$v$::jsonb
