UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "المراهنات على نتائج المباريات، ورسوم الاشتراك في المسابقات إذا كانت هي مصدر الجائزة.", "en": "Betting on match outcomes, and entry fees for competitions when they fund the prize.", "ref": "تحريم الميسر؛ حديث «لا سَبَق إلا في خفٍّ أو حافرٍ أو نصل»", "strength": "nass"}, {"kind": "condition", "ar": "الجوائز: جوازها إذا كانت من طرفٍ ثالث أو من أحد المتسابقين دون الآخر، وفق أحكام السَّبَق.", "en": "Prizes are permitted when funded by a third party or by only one contestant, per the rules of competition prizes.", "ref": "أحكام السَّبَق", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "مراعاة ستر العورات في اللباس والبث، وتوفير مرافق منفصلة في اللياقة حيث تقتضيه الضوابط.", "en": "Observe modesty in attire and broadcasting, and provide separate fitness facilities where the guidelines require.", "ref": "أحكام العورة", "strength": "nass"}, {"kind": "condition", "ar": "عقود اللاعبين وانتقالاتهم: إجارة أشخاص بأجرٍ ومدة معلومين. ويجوز عوض فسخ العقد، ويُحال بيع حقوق اللاعبين إلى الهيئة.", "en": "Player contracts and transfers are hiring of persons with a known wage and term. Termination compensation is permitted; trading in player rights is referred to the board.", "ref": "AAOIFI المعيار الشرعي 34 (إجارة الأشخاص)", "strength": "khilaf"}, {"kind": "prohibition", "ar": "الرعاية من شركات الخمور أو القمار أو الربا، والرياضات القائمة على الإيذاء المتعمد الجسيم.", "en": "Sponsorship by alcohol, gambling or interest-based companies, and sports built on deliberate serious injury.", "ref": "النهي عن الإعانة على الإثم", "strength": "ijtihad"}, {"kind": "condition", "ar": "الرياضات الإلكترونية والألعاب: خلوّها من القمار وصناديق الغنائم المدفوعة والمحتوى المحرّم، وضبط أوقات اللعب للقُصّر.", "en": "Esports and games must be free of gambling, paid loot boxes and prohibited content, with playtime controls for minors.", "ref": "تحريم الميسر؛ مقصد حفظ العقل", "strength": "ijtihad"}]$v$::jsonb
