UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "الأتعاب: أجرة معلومة أو نسبة من مالٍ محصَّل بشروط تمنع الغرر الفاحش. وتجوز أتعاب النجاح في الحدود التي تعتمدها الهيئة.", "en": "Fees: a known fee, or a percentage of amounts recovered under terms that avoid gross gharar. Success fees are permitted within limits approved by the board.", "ref": "AAOIFI المعيار الشرعي 34 (إجارة الأشخاص)", "strength": "khilaf"}, {"kind": "prohibition", "ar": "الترافع أو الاستشارة لإثبات باطلٍ أو إسقاط حقٍّ مع العلم، وهيكلة معاملات ربوية أو التحايل على الأحكام.", "en": "Knowingly litigating or advising to establish a falsehood or defeat a right, or structuring interest-based deals or legal stratagems.", "ref": "قوله تعالى: ﴿ولا تكن للخائنين خصيمًا﴾", "strength": "nass"}, {"kind": "mandatory", "ar": "السرّية المهنية وحفظ أسرار العملاء، والإفصاح عن تعارض المصالح.", "en": "Professional confidentiality, protecting client secrets, and disclosing conflicts of interest.", "ref": "أحكام الأمانة", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "ضمان الخطأ المهني: يضمن المهني ما نتج عن تعدّيه أو تقصيره عن المعايير المهنية المعتبرة.", "en": "Professional liability: the professional is liable for losses from transgression or falling short of recognised professional standards.", "ref": "أحكام ضمان الأجير", "strength": "ijma"}, {"kind": "condition", "ar": "المراجعة والمحاسبة: تطبيق المعايير المحاسبية لأيوفي للمؤسسات المالية الإسلامية، والإفصاح عن الدخل غير المباح.", "en": "Audit and accounting: apply AAOIFI accounting standards for Islamic financial institutions and disclose non-permissible income.", "ref": "معايير المحاسبة الصادرة عن أيوفي", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "في الهندسة والعمارة: السلامة الإنشائية، والوفاء بالمواصفات، وعدم تصميم ما يُتخذ للمحرّم أصالةً.", "en": "In engineering and architecture: structural safety, meeting specifications, and not designing facilities intended mainly for prohibited use.", "ref": "قاعدة «لا ضرر ولا ضرار»", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$M$v$ AND requirements = $v$[{"kind": "condition", "ar": "الأتعاب: أجرة معلومة أو نسبة من مالٍ محصَّل بشروط تمنع الغرر الفاحش. وتجوز أتعاب النجاح في الحدود التي تعتمدها الهيئة.", "en": "Fees: a known fee, or a percentage of amounts recovered under terms that avoid gross gharar. Success fees are permitted within limits approved by the board.", "ref": "AAOIFI المعيار الشرعي 34 (إجارة الأشخاص)"}, {"kind": "prohibition", "ar": "الترافع أو الاستشارة لإثبات باطلٍ أو إسقاط حقٍّ مع العلم، وهيكلة معاملات ربوية أو التحايل على الأحكام.", "en": "Knowingly litigating or advising to establish a falsehood or defeat a right, or structuring interest-based deals or legal stratagems.", "ref": "قوله تعالى: ﴿ولا تكن للخائنين خصيمًا﴾"}, {"kind": "mandatory", "ar": "السرّية المهنية وحفظ أسرار العملاء، والإفصاح عن تعارض المصالح.", "en": "Professional confidentiality, protecting client secrets, and disclosing conflicts of interest.", "ref": "أحكام الأمانة"}, {"kind": "mandatory", "ar": "ضمان الخطأ المهني: يضمن المهني ما نتج عن تعدّيه أو تقصيره عن المعايير المهنية المعتبرة.", "en": "Professional liability: the professional is liable for losses from transgression or falling short of recognised professional standards.", "ref": "أحكام ضمان الأجير"}, {"kind": "condition", "ar": "المراجعة والمحاسبة: تطبيق المعايير المحاسبية لأيوفي للمؤسسات المالية الإسلامية، والإفصاح عن الدخل غير المباح.", "en": "Audit and accounting: apply AAOIFI accounting standards for Islamic financial institutions and disclose non-permissible income.", "ref": "معايير المحاسبة الصادرة عن أيوفي"}, {"kind": "mandatory", "ar": "في الهندسة والعمارة: السلامة الإنشائية، والوفاء بالمواصفات، وعدم تصميم ما يُتخذ للمحرّم أصالةً.", "en": "In engineering and architecture: structural safety, meeting specifications, and not designing facilities intended mainly for prohibited use.", "ref": "قاعدة «لا ضرر ولا ضرار»"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "التأجير التشغيلي للمعدات: تحمّل المؤجر الصيانة الأساسية والهلاك، والأجرة معلومة لكل فترة.", "en": "Operating leases of equipment: the lessor bears major maintenance and loss, with a known rent for each period.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)", "strength": "ijma"}, {"kind": "mandatory", "ar": "خدمات التوظيف والعمالة المؤقتة: وضوح الأجر والمدة، وعدم احتجاز الوثائق، ومنع استيفاء رسوم استقدام من العامل على وجه الظلم.", "en": "Staffing and temporary labour: clear wages and terms, no withholding of documents, and no unfair recruitment fees charged to workers.", "ref": "حديث «أعطوا الأجير أجره»", "strength": "nass"}, {"kind": "condition", "ar": "تحصيل الديون: جواز أجرة التحصيل المعلومة، ومنع الأساليب المهينة، ومنع احتساب فوائد على المدين.", "en": "Debt collection: a known collection fee is permitted; no humiliating methods and no interest charged to the debtor.", "ref": "AAOIFI المعيار الشرعي 3 (المدين المماطل)", "strength": "ijma"}, {"kind": "prohibition", "ar": "تقديم خدمات مساندة أساسية لنشاطٍ محرّمٍ ظاهر، كإدارة صالات القمار أو التسويق لمنتجات ربوية.", "en": "Providing core support services to a clearly prohibited activity, such as managing casinos or marketing interest-based products.", "ref": "النهي عن الإعانة على الإثم", "strength": "ijtihad"}, {"kind": "condition", "ar": "الوكالة بأجر في الخدمات الإدارية: بيان محل الوكالة وحدودها والأجر، والوكيل أمين لا يضمن إلا بالتعدي أو التقصير.", "en": "Paid agency in administrative services: define the mandate, limits and fee; the agent is a trustee liable only for transgression or negligence.", "ref": "AAOIFI المعيار الشرعي 23 (الوكالة)", "strength": "ijma"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$N$v$ AND requirements = $v$[{"kind": "condition", "ar": "التأجير التشغيلي للمعدات: تحمّل المؤجر الصيانة الأساسية والهلاك، والأجرة معلومة لكل فترة.", "en": "Operating leases of equipment: the lessor bears major maintenance and loss, with a known rent for each period.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)"}, {"kind": "mandatory", "ar": "خدمات التوظيف والعمالة المؤقتة: وضوح الأجر والمدة، وعدم احتجاز الوثائق، ومنع استيفاء رسوم استقدام من العامل على وجه الظلم.", "en": "Staffing and temporary labour: clear wages and terms, no withholding of documents, and no unfair recruitment fees charged to workers.", "ref": "حديث «أعطوا الأجير أجره»"}, {"kind": "condition", "ar": "تحصيل الديون: جواز أجرة التحصيل المعلومة، ومنع الأساليب المهينة، ومنع احتساب فوائد على المدين.", "en": "Debt collection: a known collection fee is permitted; no humiliating methods and no interest charged to the debtor.", "ref": "AAOIFI المعيار الشرعي 3 (المدين المماطل)"}, {"kind": "prohibition", "ar": "تقديم خدمات مساندة أساسية لنشاطٍ محرّمٍ ظاهر، كإدارة صالات القمار أو التسويق لمنتجات ربوية.", "en": "Providing core support services to a clearly prohibited activity, such as managing casinos or marketing interest-based products.", "ref": "النهي عن الإعانة على الإثم"}, {"kind": "condition", "ar": "الوكالة بأجر في الخدمات الإدارية: بيان محل الوكالة وحدودها والأجر، والوكيل أمين لا يضمن إلا بالتعدي أو التقصير.", "en": "Paid agency in administrative services: define the mandate, limits and fee; the agent is a trustee liable only for transgression or negligence.", "ref": "AAOIFI المعيار الشرعي 23 (الوكالة)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "خدمات التجميل المحرّمة كالوشم الدائم ووصل الشعر والنمص المنهي عنه، والتصوير المخلّ بالآداب.", "en": "Prohibited beauty services such as permanent tattoos, hair extensions and forbidden eyebrow plucking, and indecent photography.", "ref": "حديث لعن الواصلة والمستوصلة والواشمة", "strength": "nass"}, {"kind": "mandatory", "ar": "الستر والفصل بين الجنسين في الخدمات التي تقتضي الملامسة أو كشف العورة.", "en": "Modesty and gender separation in services involving touch or uncovering.", "ref": "أحكام العورة", "strength": "ijtihad"}, {"kind": "condition", "ar": "الإصلاح والصيانة: أجرة معلومة، وضمان ما تلف بالتعدي أو التقصير، والصدق في بيان الأعطال وقطع الغيار.", "en": "Repair and maintenance: a known fee, liability for damage from transgression or negligence, and honesty about faults and spare parts.", "ref": "أحكام الأجير المشترك", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "الطهارة والنظافة في خدمات الغسيل والعناية الشخصية.", "en": "Cleanliness and purity in laundry and personal care services.", "ref": "أحكام الطهارة", "strength": "ijtihad"}, {"kind": "condition", "ar": "الجمعيات والنقابات المهنية: شفافية الاشتراكات وصرفها في أغراضها، واجتناب استثمار الفائض في محرّم.", "en": "Professional associations: transparent membership fees spent on their purposes, and no investment of surplus in prohibited assets.", "ref": "أحكام الأمانة", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$S$v$ AND requirements = $v$[{"kind": "prohibition", "ar": "خدمات التجميل المحرّمة كالوشم الدائم ووصل الشعر والنمص المنهي عنه، والتصوير المخلّ بالآداب.", "en": "Prohibited beauty services such as permanent tattoos, hair extensions and forbidden eyebrow plucking, and indecent photography.", "ref": "حديث لعن الواصلة والمستوصلة والواشمة"}, {"kind": "mandatory", "ar": "الستر والفصل بين الجنسين في الخدمات التي تقتضي الملامسة أو كشف العورة.", "en": "Modesty and gender separation in services involving touch or uncovering.", "ref": "أحكام العورة"}, {"kind": "condition", "ar": "الإصلاح والصيانة: أجرة معلومة، وضمان ما تلف بالتعدي أو التقصير، والصدق في بيان الأعطال وقطع الغيار.", "en": "Repair and maintenance: a known fee, liability for damage from transgression or negligence, and honesty about faults and spare parts.", "ref": "أحكام الأجير المشترك"}, {"kind": "mandatory", "ar": "الطهارة والنظافة في خدمات الغسيل والعناية الشخصية.", "en": "Cleanliness and purity in laundry and personal care services.", "ref": "أحكام الطهارة"}, {"kind": "condition", "ar": "الجمعيات والنقابات المهنية: شفافية الاشتراكات وصرفها في أغراضها، واجتناب استثمار الفائض في محرّم.", "en": "Professional associations: transparent membership fees spent on their purposes, and no investment of surplus in prohibited assets.", "ref": "أحكام الأمانة"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "الوقف: الالتزام بشرط الواقف، وحفظ الأصل الموقوف، واستثماره بالصيغ المشروعة، وصرف الريع في مصارفه.", "en": "Waqf: honour the endower's conditions, preserve the endowed asset, invest it through lawful structures, and spend income on its designated purposes.", "ref": "AAOIFI المعيار الشرعي 33 (الوقف)", "strength": "ijma"}, {"kind": "mandatory", "ar": "الزكاة: صرفها في مصارفها الثمانية دون غيرها، وفصل حساباتها عن التبرعات العامة، والتمليك للمستحق حيث يُشترط.", "en": "Zakat: spend it only on its eight channels, keep its accounts separate from general donations, and transfer ownership to recipients where required.", "ref": "قوله تعالى: ﴿إنما الصدقات للفقراء…﴾؛ AAOIFI المعيار الشرعي 35", "strength": "nass"}, {"kind": "mandatory", "ar": "التبرعات المقيدة تُصرف فيما قُيّدت له، ويُستأذن المتبرع عند تعذّر ذلك.", "en": "Restricted donations are spent as restricted; donor permission is sought when that is not possible.", "ref": "أحكام الوكالة والأمانة", "strength": "ijtihad"}, {"kind": "condition", "ar": "نفقات إدارة الجمعيات: في حدود معقولة ومفصح عنها. وحصة العاملين على الزكاة وفق ضوابط الهيئة.", "en": "Administrative costs are reasonable and disclosed; the share of zakat administrators follows the board's rules.", "ref": "مصرف «العاملين عليها»", "strength": "ijtihad"}, {"kind": "condition", "ar": "الاستثمار: استثمار الفوائض والأوقاف في أصول متوافقة وبمخاطر منضبطة، واجتناب الودائع الربوية.", "en": "Investment: invest surpluses and endowments in compliant assets with controlled risk, avoiding interest-bearing deposits.", "ref": "AAOIFI المعيار الشرعي 21", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "في الخدمات الدينية: أهلية الفتوى والتعليم، وضبط رسوم الحج والعمرة وخدمات المساجد بالعدل والشفافية.", "en": "In religious services: qualified fatwa and teaching, and fair, transparent fees for Hajj, Umrah and mosque services.", "ref": "أحكام الفتوى وآدابها", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$S2$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "الوقف: الالتزام بشرط الواقف، وحفظ الأصل الموقوف، واستثماره بالصيغ المشروعة، وصرف الريع في مصارفه.", "en": "Waqf: honour the endower's conditions, preserve the endowed asset, invest it through lawful structures, and spend income on its designated purposes.", "ref": "AAOIFI المعيار الشرعي 33 (الوقف)"}, {"kind": "mandatory", "ar": "الزكاة: صرفها في مصارفها الثمانية دون غيرها، وفصل حساباتها عن التبرعات العامة، والتمليك للمستحق حيث يُشترط.", "en": "Zakat: spend it only on its eight channels, keep its accounts separate from general donations, and transfer ownership to recipients where required.", "ref": "قوله تعالى: ﴿إنما الصدقات للفقراء…﴾؛ AAOIFI المعيار الشرعي 35"}, {"kind": "mandatory", "ar": "التبرعات المقيدة تُصرف فيما قُيّدت له، ويُستأذن المتبرع عند تعذّر ذلك.", "en": "Restricted donations are spent as restricted; donor permission is sought when that is not possible.", "ref": "أحكام الوكالة والأمانة"}, {"kind": "condition", "ar": "نفقات إدارة الجمعيات: في حدود معقولة ومفصح عنها. وحصة العاملين على الزكاة وفق ضوابط الهيئة.", "en": "Administrative costs are reasonable and disclosed; the share of zakat administrators follows the board's rules.", "ref": "مصرف «العاملين عليها»"}, {"kind": "condition", "ar": "الاستثمار: استثمار الفوائض والأوقاف في أصول متوافقة وبمخاطر منضبطة، واجتناب الودائع الربوية.", "en": "Investment: invest surpluses and endowments in compliant assets with controlled risk, avoiding interest-bearing deposits.", "ref": "AAOIFI المعيار الشرعي 21"}, {"kind": "mandatory", "ar": "في الخدمات الدينية: أهلية الفتوى والتعليم، وضبط رسوم الحج والعمرة وخدمات المساجد بالعدل والشفافية.", "en": "In religious services: qualified fatwa and teaching, and fair, transparent fees for Hajj, Umrah and mosque services.", "ref": "أحكام الفتوى وآدابها"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "عقد الحراسة إجارةٌ على عمل: بيان المحل والمدة والأجرة، والحارس أمين يضمن بالتعدي أو التفريط.", "en": "A guarding contract is a hire of services: specify the site, term and fee; the guard is a trustee liable for transgression or negligence.", "ref": "AAOIFI المعيار الشرعي 34 (إجارة الأشخاص)", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "استعمال القوة في حدود دفع الصائل وبقدر الحاجة، وفق الأنظمة، دون اعتداء.", "en": "Use force only to repel aggression and only as needed, within the law, without aggression.", "ref": "أحكام دفع الصائل", "strength": "ijma"}, {"kind": "prohibition", "ar": "حراسة المنشآت المحرّمة أصالةً كالكازينوهات، والتجسّس على الناس بغير مسوّغ نظامي.", "en": "Guarding inherently prohibited venues such as casinos, and spying on people without legal grounds.", "ref": "قوله تعالى: ﴿ولا تجسّسوا﴾", "strength": "nass"}, {"kind": "mandatory", "ar": "حفظ الأسرار والبيانات والتسجيلات، وعدم استعمالها لغير الغرض الأمني المحدد.", "en": "Protect secrets, data and recordings, and never use them beyond the stated security purpose.", "ref": "أحكام الأمانة", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "حقوق الحراس: أجرٌ عادل، وساعات معقولة، وتدريب وتجهيز يحفظ النفس.", "en": "Guards' rights: fair pay, reasonable hours, and training and equipment that protect life.", "ref": "مقصد حفظ النفس", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$N2$v$ AND requirements = $v$[{"kind": "condition", "ar": "عقد الحراسة إجارةٌ على عمل: بيان المحل والمدة والأجرة، والحارس أمين يضمن بالتعدي أو التفريط.", "en": "A guarding contract is a hire of services: specify the site, term and fee; the guard is a trustee liable for transgression or negligence.", "ref": "AAOIFI المعيار الشرعي 34 (إجارة الأشخاص)"}, {"kind": "mandatory", "ar": "استعمال القوة في حدود دفع الصائل وبقدر الحاجة، وفق الأنظمة، دون اعتداء.", "en": "Use force only to repel aggression and only as needed, within the law, without aggression.", "ref": "أحكام دفع الصائل"}, {"kind": "prohibition", "ar": "حراسة المنشآت المحرّمة أصالةً كالكازينوهات، والتجسّس على الناس بغير مسوّغ نظامي.", "en": "Guarding inherently prohibited venues such as casinos, and spying on people without legal grounds.", "ref": "قوله تعالى: ﴿ولا تجسّسوا﴾"}, {"kind": "mandatory", "ar": "حفظ الأسرار والبيانات والتسجيلات، وعدم استعمالها لغير الغرض الأمني المحدد.", "en": "Protect secrets, data and recordings, and never use them beyond the stated security purpose.", "ref": "أحكام الأمانة"}, {"kind": "mandatory", "ar": "حقوق الحراس: أجرٌ عادل، وساعات معقولة، وتدريب وتجهيز يحفظ النفس.", "en": "Guards' rights: fair pay, reasonable hours, and training and equipment that protect life.", "ref": "مقصد حفظ النفس"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "الأصل في المنافع المستجدة الإباحة، مع النظر في المآلات. وكل نازلة لم يُعرف لها حكمٌ مستقر تُصنَّف «قيد الدراسة / إحالة» ولا تُقحم في مرتبة قسرًا.", "en": "New benefits are permissible by default, with regard to outcomes. Any novel matter without a settled ruling is classed \"under study / referral\" and not forced into a rank.", "ref": "الحالات الخاصة في المعيار؛ قاعدة اعتبار المآلات", "strength": "ijtihad"}, {"kind": "condition", "ar": "الأصول الافتراضية وعوالم الميتافيرس: يُحال تملّك الأصول الرقمية والرموز غير القابلة للاستبدال وتداولها إلى الهيئة، مع منع المضاربة القائمة على الرهان.", "en": "Virtual assets and metaverses: ownership and trading of digital assets and NFTs are referred to the board, and betting-based speculation is prohibited.", "ref": "قرار مجمع الفقه 237 بالتوقف", "strength": "khilaf"}, {"kind": "condition", "ar": "التقنية الحيوية المتقدمة: الالتزام بقرارات المجامع في الهندسة الوراثية، ومنع التعديل الوراثي البشري لغير العلاج.", "en": "Advanced biotechnology: follow fiqh academy resolutions on genetic engineering, and no human genetic modification except for treatment.", "ref": "قرارات مجمع الفقه الإسلامي في الهندسة الوراثية", "strength": "ijma"}, {"kind": "condition", "ar": "الأتمتة والروبوتات: مسؤولية المشغّل عن الضرر، ورعاية العاملين المتأثرين بالتأهيل وإعادة التوظيف.", "en": "Automation and robotics: operator liability for harm, and care for affected workers through retraining and redeployment.", "ref": "قاعدة «الغُرم بالغُنم»", "strength": "ijtihad"}, {"kind": "condition", "ar": "تمويل ريادة الأعمال: المشاركة والمضاربة، واجتناب أدوات الدين التقليدية القابلة للتحويل بفائدة.", "en": "Entrepreneurship financing: musharakah and mudarabah, avoiding conventional interest-bearing convertible debt.", "ref": "AAOIFI المعياران الشرعيان 12 و13", "strength": "ijtihad"}, {"kind": "recommended", "ar": "الاقتصاد الأخضر: تشجيع مشروعات الطاقة النظيفة والاستدامة بوصفها من حفظ المال والنفس، وتكييف أدواتها بالصيغ المشروعة.", "en": "Green economy: encourage clean energy and sustainability projects as preserving wealth and life, using lawful structures.", "ref": "مقاصد الشريعة", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$X$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "الأصل في المنافع المستجدة الإباحة، مع النظر في المآلات. وكل نازلة لم يُعرف لها حكمٌ مستقر تُصنَّف «قيد الدراسة / إحالة» ولا تُقحم في مرتبة قسرًا.", "en": "New benefits are permissible by default, with regard to outcomes. Any novel matter without a settled ruling is classed \"under study / referral\" and not forced into a rank.", "ref": "الحالات الخاصة في المعيار؛ قاعدة اعتبار المآلات"}, {"kind": "condition", "ar": "الأصول الافتراضية وعوالم الميتافيرس: يُحال تملّك الأصول الرقمية والرموز غير القابلة للاستبدال وتداولها إلى الهيئة، مع منع المضاربة القائمة على الرهان.", "en": "Virtual assets and metaverses: ownership and trading of digital assets and NFTs are referred to the board, and betting-based speculation is prohibited.", "ref": "قرار مجمع الفقه 237 بالتوقف"}, {"kind": "condition", "ar": "التقنية الحيوية المتقدمة: الالتزام بقرارات المجامع في الهندسة الوراثية، ومنع التعديل الوراثي البشري لغير العلاج.", "en": "Advanced biotechnology: follow fiqh academy resolutions on genetic engineering, and no human genetic modification except for treatment.", "ref": "قرارات مجمع الفقه الإسلامي في الهندسة الوراثية"}, {"kind": "condition", "ar": "الأتمتة والروبوتات: مسؤولية المشغّل عن الضرر، ورعاية العاملين المتأثرين بالتأهيل وإعادة التوظيف.", "en": "Automation and robotics: operator liability for harm, and care for affected workers through retraining and redeployment.", "ref": "قاعدة «الغُرم بالغُنم»"}, {"kind": "condition", "ar": "تمويل ريادة الأعمال: المشاركة والمضاربة، واجتناب أدوات الدين التقليدية القابلة للتحويل بفائدة.", "en": "Entrepreneurship financing: musharakah and mudarabah, avoiding conventional interest-bearing convertible debt.", "ref": "AAOIFI المعياران الشرعيان 12 و13"}, {"kind": "recommended", "ar": "الاقتصاد الأخضر: تشجيع مشروعات الطاقة النظيفة والاستدامة بوصفها من حفظ المال والنفس، وتكييف أدواتها بالصيغ المشروعة.", "en": "Green economy: encourage clean energy and sustainability projects as preserving wealth and life, using lawful structures.", "ref": "مقاصد الشريعة"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "في المرجعيات الشرعية: أهلية المفتين، والاجتهاد الجماعي في النوازل، ونشر القرارات بأدلتها ومناهج الترجيح.", "en": "In religious reference bodies: qualified muftis, collective ijtihad on novel matters, and publishing decisions with their evidence and methods of preference.", "ref": "ضوابط الفتوى وآدابها", "strength": "ijtihad"}, {"kind": "condition", "ar": "الهيئات التنظيمية المالية: تمكين المؤسسات المالية الإسلامية بإطار تنظيمي مناسب، وعدم إلزامها بما يخالف أحكامها.", "en": "Financial regulators: provide a suitable regulatory framework for Islamic financial institutions and do not compel them to breach their rules.", "ref": "قاعدة «تصرّف الإمام على الرعية منوطٌ بالمصلحة»", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "المال العام: الشفافية في الموازنات، والمساءلة، ومنع الإسراف والهدر.", "en": "Public funds: transparent budgets, accountability, and no extravagance or waste.", "ref": "قوله تعالى: ﴿ولا تبذّر تبذيرًا﴾", "strength": "nass"}, {"kind": "condition", "ar": "المعاهدات والاتفاقيات الدولية: الوفاء بها بما لا يخالف الشرع، والتحفظ على ما يخالف أحكامه.", "en": "International treaties: honour them where consistent with Shariah, and enter reservations on what conflicts with it.", "ref": "قوله تعالى: ﴿وأوفوا بالعهد﴾", "strength": "nass"}, {"kind": "prohibition", "ar": "إصدار سياسات أو تشريعات تُلزِم الناس بالتعامل الربوي حيث توجد بدائل مشروعة، أو تبيح المحرّمات القطعية.", "en": "Issuing policies or laws that compel people into interest-based dealings where lawful alternatives exist, or that permit definitively prohibited matters.", "ref": "مقاصد الشريعة الكلية", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "المؤسسات البحثية والاستراتيجية: الاستقلال العلمي، والإفصاح عن مصادر التمويل، ومنع تضارب المصالح في التوصيات.", "en": "Research and strategy institutions: scholarly independence, disclosure of funding sources, and no conflicts of interest in recommendations.", "ref": "أحكام الأمانة", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'industry' AND node_key = $v$O$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "في المرجعيات الشرعية: أهلية المفتين، والاجتهاد الجماعي في النوازل، ونشر القرارات بأدلتها ومناهج الترجيح.", "en": "In religious reference bodies: qualified muftis, collective ijtihad on novel matters, and publishing decisions with their evidence and methods of preference.", "ref": "ضوابط الفتوى وآدابها"}, {"kind": "condition", "ar": "الهيئات التنظيمية المالية: تمكين المؤسسات المالية الإسلامية بإطار تنظيمي مناسب، وعدم إلزامها بما يخالف أحكامها.", "en": "Financial regulators: provide a suitable regulatory framework for Islamic financial institutions and do not compel them to breach their rules.", "ref": "قاعدة «تصرّف الإمام على الرعية منوطٌ بالمصلحة»"}, {"kind": "mandatory", "ar": "المال العام: الشفافية في الموازنات، والمساءلة، ومنع الإسراف والهدر.", "en": "Public funds: transparent budgets, accountability, and no extravagance or waste.", "ref": "قوله تعالى: ﴿ولا تبذّر تبذيرًا﴾"}, {"kind": "condition", "ar": "المعاهدات والاتفاقيات الدولية: الوفاء بها بما لا يخالف الشرع، والتحفظ على ما يخالف أحكامه.", "en": "International treaties: honour them where consistent with Shariah, and enter reservations on what conflicts with it.", "ref": "قوله تعالى: ﴿وأوفوا بالعهد﴾"}, {"kind": "prohibition", "ar": "إصدار سياسات أو تشريعات تُلزِم الناس بالتعامل الربوي حيث توجد بدائل مشروعة، أو تبيح المحرّمات القطعية.", "en": "Issuing policies or laws that compel people into interest-based dealings where lawful alternatives exist, or that permit definitively prohibited matters.", "ref": "مقاصد الشريعة الكلية"}, {"kind": "mandatory", "ar": "المؤسسات البحثية والاستراتيجية: الاستقلال العلمي، والإفصاح عن مصادر التمويل، ومنع تضارب المصالح في التوصيات.", "en": "Research and strategy institutions: scholarly independence, disclosure of funding sources, and no conflicts of interest in recommendations.", "ref": "أحكام الأمانة"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "الإقراض والإيداع بفائدة؛ فالقرض عقد إرفاق لا معاوضة، وكل قرضٍ جرّ نفعًا مشروطًا فهو ربا.", "en": "Lending or taking deposits at interest; a loan is an act of benevolence, not exchange, and any loan that brings a stipulated benefit is riba.", "ref": "AAOIFI المعيار الشرعي 19 (القرض)", "strength": "nass"}, {"kind": "mandatory", "ar": "التمويل بالصيغ المشروعة: المرابحة للآمر بالشراء، والإجارة المنتهية بالتمليك، والمشاركة المتناقصة، والاستصناع.", "en": "Finance through lawful structures: murabahah to the purchase orderer, ijarah ending in ownership, diminishing musharakah, and istisna'.", "ref": "AAOIFI المعايير الشرعية 8 و9 و11 و12", "strength": "ijma"}, {"kind": "mandatory", "ar": "تملّك المصرف للسلعة وقبضها قبضًا حقيقيًّا أو حكميًّا معتبرًا قبل بيعها مرابحة.", "en": "The bank must own the goods and take real or valid constructive possession before selling them by murabahah.", "ref": "AAOIFI المعيار الشرعي 18 (القبض)", "strength": "ijma"}, {"kind": "prohibition", "ar": "بيع العِينة، والتورّق المنظّم الذي لا حقيقة للسلعة فيه، وغرامات التأخير التي تعود للمصرف ربحًا.", "en": "'Inah sales, organised tawarruq with no real commodity, and late-payment charges retained by the bank as profit.", "ref": "AAOIFI المعياران الشرعيان 3 و30", "strength": "ijma"}, {"kind": "mandatory", "ar": "هيئة رقابة شرعية مستقلة، وتدقيق شرعي دوري، وتطهير الإيراد غير المباح وصرفه في وجوه الخير دون أن ينتفع به المصرف.", "en": "An independent Shariah board, periodic Shariah audit, and purification of non-permissible income given to charity without benefit to the bank.", "ref": "معايير الحوكمة لأيوفي", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:المصرفية للأفراد والشركات$v$ AND requirements = $v$[{"kind": "prohibition", "ar": "الإقراض والإيداع بفائدة؛ فالقرض عقد إرفاق لا معاوضة، وكل قرضٍ جرّ نفعًا مشروطًا فهو ربا.", "en": "Lending or taking deposits at interest; a loan is an act of benevolence, not exchange, and any loan that brings a stipulated benefit is riba.", "ref": "AAOIFI المعيار الشرعي 19 (القرض)"}, {"kind": "mandatory", "ar": "التمويل بالصيغ المشروعة: المرابحة للآمر بالشراء، والإجارة المنتهية بالتمليك، والمشاركة المتناقصة، والاستصناع.", "en": "Finance through lawful structures: murabahah to the purchase orderer, ijarah ending in ownership, diminishing musharakah, and istisna'.", "ref": "AAOIFI المعايير الشرعية 8 و9 و11 و12"}, {"kind": "mandatory", "ar": "تملّك المصرف للسلعة وقبضها قبضًا حقيقيًّا أو حكميًّا معتبرًا قبل بيعها مرابحة.", "en": "The bank must own the goods and take real or valid constructive possession before selling them by murabahah.", "ref": "AAOIFI المعيار الشرعي 18 (القبض)"}, {"kind": "prohibition", "ar": "بيع العِينة، والتورّق المنظّم الذي لا حقيقة للسلعة فيه، وغرامات التأخير التي تعود للمصرف ربحًا.", "en": "'Inah sales, organised tawarruq with no real commodity, and late-payment charges retained by the bank as profit.", "ref": "AAOIFI المعياران الشرعيان 3 و30"}, {"kind": "mandatory", "ar": "هيئة رقابة شرعية مستقلة، وتدقيق شرعي دوري، وتطهير الإيراد غير المباح وصرفه في وجوه الخير دون أن ينتفع به المصرف.", "en": "An independent Shariah board, periodic Shariah audit, and purification of non-permissible income given to charity without benefit to the bank.", "ref": "معايير الحوكمة لأيوفي"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "أن يمثّل الصك حصة شائعة في أعيان أو منافع أو خدمات أو موجودات مشروع، لا دينًا في ذمة المُصدِر.", "en": "A sukuk certificate must represent an undivided share in assets, usufruct, services or project assets, not a debt owed by the issuer.", "ref": "AAOIFI المعيار الشرعي 17 (صكوك الاستثمار)", "strength": "ijma"}, {"kind": "prohibition", "ar": "ضمان المُصدِر أو المدير لرأس المال أو لعائد ثابت؛ فحملة الصكوك يتحملون الغنم والغرم بحسب ملكيتهم.", "en": "The issuer or manager guaranteeing capital or a fixed return; holders share profit and loss according to ownership.", "ref": "AAOIFI المعيار الشرعي 17", "strength": "ijma"}, {"kind": "condition", "ar": "تداول صكوك المرابحة والسلم بعد التنضيض أو صيرورة موجوداتها ديونًا لا يجوز إلا بضوابط تداول الدين والصرف.", "en": "Murabahah and salam sukuk whose assets have become debts may only be traded under the rules on debt and currency exchange.", "ref": "AAOIFI المعيار الشرعي 17", "strength": "ijma"}, {"kind": "condition", "ar": "يجوز تعهّد المدير بالشراء بالقيمة السوقية أو بثمن يُتفق عليه عند الشراء، لا بالقيمة الاسمية.", "en": "A manager's purchase undertaking is permitted at market value or a price agreed at the time of purchase, not at par.", "ref": "AAOIFI المعيار الشرعي 17", "strength": "ijma"}, {"kind": "mandatory", "ar": "الإفصاح في نشرة الإصدار عن الهيكل والموجودات والمخاطر ورأي الهيئة الشرعية.", "en": "Disclose the structure, assets, risks and the Shariah board's opinion in the prospectus.", "ref": "مبدأ الشفافية", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:الصكوك$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "أن يمثّل الصك حصة شائعة في أعيان أو منافع أو خدمات أو موجودات مشروع، لا دينًا في ذمة المُصدِر.", "en": "A sukuk certificate must represent an undivided share in assets, usufruct, services or project assets, not a debt owed by the issuer.", "ref": "AAOIFI المعيار الشرعي 17 (صكوك الاستثمار)"}, {"kind": "prohibition", "ar": "ضمان المُصدِر أو المدير لرأس المال أو لعائد ثابت؛ فحملة الصكوك يتحملون الغنم والغرم بحسب ملكيتهم.", "en": "The issuer or manager guaranteeing capital or a fixed return; holders share profit and loss according to ownership.", "ref": "AAOIFI المعيار الشرعي 17"}, {"kind": "condition", "ar": "تداول صكوك المرابحة والسلم بعد التنضيض أو صيرورة موجوداتها ديونًا لا يجوز إلا بضوابط تداول الدين والصرف.", "en": "Murabahah and salam sukuk whose assets have become debts may only be traded under the rules on debt and currency exchange.", "ref": "AAOIFI المعيار الشرعي 17"}, {"kind": "condition", "ar": "يجوز تعهّد المدير بالشراء بالقيمة السوقية أو بثمن يُتفق عليه عند الشراء، لا بالقيمة الاسمية.", "en": "A manager's purchase undertaking is permitted at market value or a price agreed at the time of purchase, not at par.", "ref": "AAOIFI المعيار الشرعي 17"}, {"kind": "mandatory", "ar": "الإفصاح في نشرة الإصدار عن الهيكل والموجودات والمخاطر ورأي الهيئة الشرعية.", "en": "Disclose the structure, assets, risks and the Shariah board's opinion in the prospectus.", "ref": "مبدأ الشفافية"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "الزيادة على القرض الحسن بأي اسم، ولو سُمّيت رسمًا أو عمولة مرتبطة بمبلغ القرض أو مدته.", "en": "Any increase on a benevolent loan under any name, even if called a fee or commission linked to the loan amount or term.", "ref": "AAOIFI المعيار الشرعي 19 (القرض)", "strength": "nass"}, {"kind": "condition", "ar": "تجوز أجرة الخدمة الفعلية المقطوعة بقدر التكلفة، دون ربطها بمقدار القرض.", "en": "A flat fee for actual service at cost is permitted, not linked to the loan amount.", "ref": "قرار مجمع الفقه الإسلامي في أجور خدمات القروض", "strength": "ijma"}, {"kind": "condition", "ar": "التمويل الإنتاجي بالمشاركة والمضاربة والمرابحة والسلم بحسب طبيعة المشروع.", "en": "Productive finance through musharakah, mudarabah, murabahah or salam according to the project.", "ref": "AAOIFI المعايير الشرعية 8 و10 و12 و13", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "مراعاة مقصد التمكين: تقييم القدرة على السداد، وإنظار المعسر، ومنع أساليب التحصيل المهينة.", "en": "Serve empowerment: assess repayment capacity, grant respite to those in hardship, and avoid humiliating collection.", "ref": "قوله تعالى: ﴿وإن كان ذو عسرةٍ فنظرةٌ إلى ميسرة﴾", "strength": "nass"}, {"kind": "condition", "ar": "ما يُلتزم به عند المماطلة من تبرّع يُصرف في الخير ولا يعود للمموّل.", "en": "Any charitable undertaking on default goes to charity, not to the financier.", "ref": "AAOIFI المعيار الشرعي 3", "strength": "ijma"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:التمويل الأصغر$v$ AND requirements = $v$[{"kind": "prohibition", "ar": "الزيادة على القرض الحسن بأي اسم، ولو سُمّيت رسمًا أو عمولة مرتبطة بمبلغ القرض أو مدته.", "en": "Any increase on a benevolent loan under any name, even if called a fee or commission linked to the loan amount or term.", "ref": "AAOIFI المعيار الشرعي 19 (القرض)"}, {"kind": "condition", "ar": "تجوز أجرة الخدمة الفعلية المقطوعة بقدر التكلفة، دون ربطها بمقدار القرض.", "en": "A flat fee for actual service at cost is permitted, not linked to the loan amount.", "ref": "قرار مجمع الفقه الإسلامي في أجور خدمات القروض"}, {"kind": "condition", "ar": "التمويل الإنتاجي بالمشاركة والمضاربة والمرابحة والسلم بحسب طبيعة المشروع.", "en": "Productive finance through musharakah, mudarabah, murabahah or salam according to the project.", "ref": "AAOIFI المعايير الشرعية 8 و10 و12 و13"}, {"kind": "mandatory", "ar": "مراعاة مقصد التمكين: تقييم القدرة على السداد، وإنظار المعسر، ومنع أساليب التحصيل المهينة.", "en": "Serve empowerment: assess repayment capacity, grant respite to those in hardship, and avoid humiliating collection.", "ref": "قوله تعالى: ﴿وإن كان ذو عسرةٍ فنظرةٌ إلى ميسرة﴾"}, {"kind": "condition", "ar": "ما يُلتزم به عند المماطلة من تبرّع يُصرف في الخير ولا يعود للمموّل.", "en": "Any charitable undertaking on default goes to charity, not to the financier.", "ref": "AAOIFI المعيار الشرعي 3"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "حصر الاستثمار في الأنشطة المباحة، وتطبيق الفرز الشرعي على الأسهم.", "en": "Invest only in permissible activities and apply Shariah screening to equities.", "ref": "AAOIFI المعيار الشرعي 21", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "فصل أموال الصندوق عن أموال المدير، والتصرف بعقد وكالة بأجر أو مضاربة.", "en": "Segregate fund assets from the manager's, acting under paid agency or mudarabah.", "ref": "AAOIFI المعياران الشرعيان 13 و23", "strength": "ijma"}, {"kind": "prohibition", "ar": "ضمان المدير لرأس المال أو الربح إلا عند التعدي أو التقصير أو مخالفة الشروط.", "en": "The manager guaranteeing capital or profit, except for transgression, negligence or breach of terms.", "ref": "أحكام الأمانة", "strength": "ijma"}, {"kind": "mandatory", "ar": "تطهير الإيراد غير المباح دوريًّا والإفصاح عن نسبته للمستثمرين.", "en": "Purify non-permissible income periodically and disclose its ratio to investors.", "ref": "AAOIFI المعيار الشرعي 21", "strength": "ijtihad"}, {"kind": "condition", "ar": "الإفصاح عن الرسوم وهيكلها، وشروط الاكتتاب والاسترداد بما ينفي الغرر.", "en": "Disclose fees and their structure, and subscription and redemption terms, so as to remove gharar.", "ref": "النهي عن الغرر", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:إدارة الأصول والصناديق$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "حصر الاستثمار في الأنشطة المباحة، وتطبيق الفرز الشرعي على الأسهم.", "en": "Invest only in permissible activities and apply Shariah screening to equities.", "ref": "AAOIFI المعيار الشرعي 21"}, {"kind": "mandatory", "ar": "فصل أموال الصندوق عن أموال المدير، والتصرف بعقد وكالة بأجر أو مضاربة.", "en": "Segregate fund assets from the manager's, acting under paid agency or mudarabah.", "ref": "AAOIFI المعياران الشرعيان 13 و23"}, {"kind": "prohibition", "ar": "ضمان المدير لرأس المال أو الربح إلا عند التعدي أو التقصير أو مخالفة الشروط.", "en": "The manager guaranteeing capital or profit, except for transgression, negligence or breach of terms.", "ref": "أحكام الأمانة"}, {"kind": "mandatory", "ar": "تطهير الإيراد غير المباح دوريًّا والإفصاح عن نسبته للمستثمرين.", "en": "Purify non-permissible income periodically and disclose its ratio to investors.", "ref": "AAOIFI المعيار الشرعي 21"}, {"kind": "condition", "ar": "الإفصاح عن الرسوم وهيكلها، وشروط الاكتتاب والاسترداد بما ينفي الغرر.", "en": "Disclose fees and their structure, and subscription and redemption terms, so as to remove gharar.", "ref": "النهي عن الغرر"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "يجوز تداول أسهم الشركات المباحة؛ فالسهم حصة شائعة في موجودات الشركة، مع تطبيق حدود الفرز والتطهير.", "en": "Trading shares of permissible companies is allowed, as a share is an undivided interest in company assets, subject to screens and purification.", "ref": "AAOIFI المعيار الشرعي 21", "strength": "ijma"}, {"kind": "prohibition", "ar": "البيع على المكشوف، والتداول بالهامش القائم على قرض ربوي، وإقراض الأسهم بعوض.", "en": "Short selling, margin trading funded by interest-bearing loans, and lending shares for a fee.", "ref": "AAOIFI المعيار الشرعي 21", "strength": "ijma"}, {"kind": "prohibition", "ar": "المشتقات القائمة على الغرر والمراهنة كالخيارات والمستقبليات المجرّدة.", "en": "Derivatives built on gharar and wagering, such as conventional options and futures.", "ref": "AAOIFI المعيار الشرعي 20", "strength": "ijma"}, {"kind": "prohibition", "ar": "النجش، والتلاعب بالأسعار، والتداول بناءً على معلومات داخلية.", "en": "Price manipulation (najsh) and insider trading.", "ref": "النهي عن النجش والغش", "strength": "nass"}, {"kind": "condition", "ar": "المؤشرات الإسلامية: بناؤها على معايير فرز معلنة ومراجعة دورية.", "en": "Islamic indices must use published screening criteria with periodic review.", "ref": "AAOIFI المعيار الشرعي 27 (المؤشرات)", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:البورصات$v$ AND requirements = $v$[{"kind": "condition", "ar": "يجوز تداول أسهم الشركات المباحة؛ فالسهم حصة شائعة في موجودات الشركة، مع تطبيق حدود الفرز والتطهير.", "en": "Trading shares of permissible companies is allowed, as a share is an undivided interest in company assets, subject to screens and purification.", "ref": "AAOIFI المعيار الشرعي 21"}, {"kind": "prohibition", "ar": "البيع على المكشوف، والتداول بالهامش القائم على قرض ربوي، وإقراض الأسهم بعوض.", "en": "Short selling, margin trading funded by interest-bearing loans, and lending shares for a fee.", "ref": "AAOIFI المعيار الشرعي 21"}, {"kind": "prohibition", "ar": "المشتقات القائمة على الغرر والمراهنة كالخيارات والمستقبليات المجرّدة.", "en": "Derivatives built on gharar and wagering, such as conventional options and futures.", "ref": "AAOIFI المعيار الشرعي 20"}, {"kind": "prohibition", "ar": "النجش، والتلاعب بالأسعار، والتداول بناءً على معلومات داخلية.", "en": "Price manipulation (najsh) and insider trading.", "ref": "النهي عن النجش والغش"}, {"kind": "condition", "ar": "المؤشرات الإسلامية: بناؤها على معايير فرز معلنة ومراجعة دورية.", "en": "Islamic indices must use published screening criteria with periodic review.", "ref": "AAOIFI المعيار الشرعي 27 (المؤشرات)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "تجوز الأجرة على خدمة التحويل والتحصيل (إجارة أو جعالة) دون ربطها بمبلغٍ على وجه القرض.", "en": "Fees for transfer and collection services (hire or ju'alah) are permitted, not tied to an amount as a loan charge.", "ref": "أحكام الإجارة والجعالة", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "أحكام الصرف عند تبادل العملات: التقابض ولو حكميًّا بالقيد الفوري، والتماثل عند اتحاد الجنس.", "en": "Currency exchange rules: hand-to-hand exchange, including constructive possession by instant booking, and equality when currencies are the same.", "ref": "AAOIFI المعيار الشرعي 1 (المتاجرة في العملات)", "strength": "nass"}, {"kind": "condition", "ar": "أرصدة المحافظ الرقمية قروض مضمونة للعميل؛ فلا يُمنح عليها عائد مشروط، ويُستثمر المصدر ما يأذن به النظام في المباح.", "en": "Wallet balances are guaranteed loans to the provider; no stipulated return may be paid on them, and any permitted investment must be in lawful assets.", "ref": "AAOIFI المعيار الشرعي 19 (القرض)", "strength": "ijma"}, {"kind": "prohibition", "ar": "تمكين المدفوعات لمواقع القمار والإباحية والإقراض الربوي.", "en": "Processing payments for gambling, pornography or interest-based lending.", "ref": "النهي عن الإعانة على الإثم", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "أمن البيانات وخصوصية المستخدم وحفظ الأمانة.", "en": "Data security, user privacy and safeguarding trust.", "ref": "أحكام الأمانة", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:المدفوعات الرقمية$v$ AND requirements = $v$[{"kind": "condition", "ar": "تجوز الأجرة على خدمة التحويل والتحصيل (إجارة أو جعالة) دون ربطها بمبلغٍ على وجه القرض.", "en": "Fees for transfer and collection services (hire or ju'alah) are permitted, not tied to an amount as a loan charge.", "ref": "أحكام الإجارة والجعالة"}, {"kind": "mandatory", "ar": "أحكام الصرف عند تبادل العملات: التقابض ولو حكميًّا بالقيد الفوري، والتماثل عند اتحاد الجنس.", "en": "Currency exchange rules: hand-to-hand exchange, including constructive possession by instant booking, and equality when currencies are the same.", "ref": "AAOIFI المعيار الشرعي 1 (المتاجرة في العملات)"}, {"kind": "condition", "ar": "أرصدة المحافظ الرقمية قروض مضمونة للعميل؛ فلا يُمنح عليها عائد مشروط، ويُستثمر المصدر ما يأذن به النظام في المباح.", "en": "Wallet balances are guaranteed loans to the provider; no stipulated return may be paid on them, and any permitted investment must be in lawful assets.", "ref": "AAOIFI المعيار الشرعي 19 (القرض)"}, {"kind": "prohibition", "ar": "تمكين المدفوعات لمواقع القمار والإباحية والإقراض الربوي.", "en": "Processing payments for gambling, pornography or interest-based lending.", "ref": "النهي عن الإعانة على الإثم"}, {"kind": "mandatory", "ar": "أمن البيانات وخصوصية المستخدم وحفظ الأمانة.", "en": "Data security, user privacy and safeguarding trust.", "ref": "أحكام الأمانة"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "التمويل بالمشاركة والمضاربة: تحديد الحصص، وقسمة الربح نسبةً شائعة، وتحمّل الخسارة بقدر رأس المال.", "en": "Musharakah and mudarabah crowdfunding: defined shares, profit split as a proportion, and losses borne by capital.", "ref": "AAOIFI المعياران الشرعيان 12 و13", "strength": "ijma"}, {"kind": "prohibition", "ar": "التمويل الإقراضي بفائدة ولو صغرت النسبة أو سُمّيت رسمًا.", "en": "Interest-bearing lending, however small the rate or whatever it is called.", "ref": "تحريم الربا", "strength": "nass"}, {"kind": "condition", "ar": "نموذجا التبرع والمكافأة جائزان بشرط الشفافية، وانتفاء الغرر الفاحش في المكافأة، والصرف في المُعلَن.", "en": "Donation and reward models are permitted with transparency, no gross gharar in rewards, and spending as announced.", "ref": "أحكام الهبة والوعد", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "فحص المنصة لمشروعية المشروعات المعروضة، والإفصاح عن المخاطر وعمولتها.", "en": "The platform vets projects for permissibility and discloses risks and its commission.", "ref": "AAOIFI المعيار الشرعي 23 (الوكالة)", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:التمويل الجماعي$v$ AND requirements = $v$[{"kind": "condition", "ar": "التمويل بالمشاركة والمضاربة: تحديد الحصص، وقسمة الربح نسبةً شائعة، وتحمّل الخسارة بقدر رأس المال.", "en": "Musharakah and mudarabah crowdfunding: defined shares, profit split as a proportion, and losses borne by capital.", "ref": "AAOIFI المعياران الشرعيان 12 و13"}, {"kind": "prohibition", "ar": "التمويل الإقراضي بفائدة ولو صغرت النسبة أو سُمّيت رسمًا.", "en": "Interest-bearing lending, however small the rate or whatever it is called.", "ref": "تحريم الربا"}, {"kind": "condition", "ar": "نموذجا التبرع والمكافأة جائزان بشرط الشفافية، وانتفاء الغرر الفاحش في المكافأة، والصرف في المُعلَن.", "en": "Donation and reward models are permitted with transparency, no gross gharar in rewards, and spending as announced.", "ref": "أحكام الهبة والوعد"}, {"kind": "mandatory", "ar": "فحص المنصة لمشروعية المشروعات المعروضة، والإفصاح عن المخاطر وعمولتها.", "en": "The platform vets projects for permissibility and discloses risks and its commission.", "ref": "AAOIFI المعيار الشرعي 23 (الوكالة)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "وضع إحالة بمخاطر S3 فأعلى: قرار مجمع الفقه الإسلامي الدولي 237 (8/24) أوصى بمزيد الدراسة ولم يصدر حكمًا قاطعًا.", "en": "Referral status at S3 risk or higher: International Islamic Fiqh Academy resolution 237 (8/24) called for further study without a final ruling.", "ref": "قرار مجمع الفقه 237 (8/24)", "strength": "khilaf"}, {"kind": "prohibition", "ar": "ما فيه قمارٌ أو مراهنة أو جهالة فاحشة، كالمشتقات بالرافعة والتداول بالهامش الربوي.", "en": "Anything involving gambling, wagering or gross uncertainty, such as leveraged derivatives and interest-funded margin trading.", "ref": "تحريم الميسر والغرر", "strength": "ijtihad"}, {"kind": "condition", "ar": "ترميز أصلٍ حقيقي مملوك أقرب إلى الجواز، والعبرة بالأصل المرمَّز لا بالتقنية.", "en": "Tokenising a real, owned asset is closer to permissibility; what matters is the underlying asset, not the technology.", "ref": "قاعدة «العبرة بالمقاصد والمعاني»", "strength": "khilaf"}, {"kind": "mandatory", "ar": "عرض كل منتج أو خدمة على هيئة شرعية مؤهلة قبل الإطلاق، وتصنيفها «قيد الدراسة» حتى يصدر القرار.", "en": "Submit every product or service to a qualified Shariah board before launch, classified \"under study\" until it rules.", "ref": "الحالات الخاصة في المعيار", "strength": "ijtihad"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:العملات والأصول المشفّرة$v$ AND requirements = $v$[{"kind": "condition", "ar": "وضع إحالة بمخاطر S3 فأعلى: قرار مجمع الفقه الإسلامي الدولي 237 (8/24) أوصى بمزيد الدراسة ولم يصدر حكمًا قاطعًا.", "en": "Referral status at S3 risk or higher: International Islamic Fiqh Academy resolution 237 (8/24) called for further study without a final ruling.", "ref": "قرار مجمع الفقه 237 (8/24)"}, {"kind": "prohibition", "ar": "ما فيه قمارٌ أو مراهنة أو جهالة فاحشة، كالمشتقات بالرافعة والتداول بالهامش الربوي.", "en": "Anything involving gambling, wagering or gross uncertainty, such as leveraged derivatives and interest-funded margin trading.", "ref": "تحريم الميسر والغرر"}, {"kind": "condition", "ar": "ترميز أصلٍ حقيقي مملوك أقرب إلى الجواز، والعبرة بالأصل المرمَّز لا بالتقنية.", "en": "Tokenising a real, owned asset is closer to permissibility; what matters is the underlying asset, not the technology.", "ref": "قاعدة «العبرة بالمقاصد والمعاني»"}, {"kind": "mandatory", "ar": "عرض كل منتج أو خدمة على هيئة شرعية مؤهلة قبل الإطلاق، وتصنيفها «قيد الدراسة» حتى يصدر القرار.", "en": "Submit every product or service to a qualified Shariah board before launch, classified \"under study\" until it rules.", "ref": "الحالات الخاصة في المعيار"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "قيام العقد على التبرع أو الالتزام بالتبرع، لا على المعاوضة الاحتمالية.", "en": "The contract rests on donation or a commitment to donate, not an aleatory exchange.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)", "strength": "ijma"}, {"kind": "mandatory", "ar": "فصل صندوق المشتركين عن أموال الشركة المديرة، وأجرة المدير وكالةً أو حصة مضاربة معلومة.", "en": "Separate the participants' fund from the operator's assets; the operator earns a known agency fee or mudarabah share.", "ref": "AAOIFI المعيار الشرعي 26", "strength": "ijma"}, {"kind": "mandatory", "ar": "استثمار أموال التكافل في المباح فقط.", "en": "Invest takaful funds only in permissible assets.", "ref": "AAOIFI المعيار الشرعي 21", "strength": "ijma"}, {"kind": "condition", "ar": "توزيع الفائض التأميني على المشتركين وفق اللائحة، ويقدّم المدير قرضًا حسنًا عند العجز.", "en": "Distribute underwriting surplus to participants per the rules; the operator provides a benevolent loan in deficit.", "ref": "AAOIFI المعيار الشرعي 26", "strength": "ijtihad"}, {"kind": "condition", "ar": "إعادة التكافل مع جهات متوافقة، وتُقبل إعادة التأمين التقليدي للحاجة بضوابط الهيئة.", "en": "Retakaful with compliant providers; conventional reinsurance is accepted only of need under board rules.", "ref": "AAOIFI المعيار الشرعي 41 (إعادة التأمين)", "strength": "khilaf"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$K:التكافل$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "قيام العقد على التبرع أو الالتزام بالتبرع، لا على المعاوضة الاحتمالية.", "en": "The contract rests on donation or a commitment to donate, not an aleatory exchange.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)"}, {"kind": "mandatory", "ar": "فصل صندوق المشتركين عن أموال الشركة المديرة، وأجرة المدير وكالةً أو حصة مضاربة معلومة.", "en": "Separate the participants' fund from the operator's assets; the operator earns a known agency fee or mudarabah share.", "ref": "AAOIFI المعيار الشرعي 26"}, {"kind": "mandatory", "ar": "استثمار أموال التكافل في المباح فقط.", "en": "Invest takaful funds only in permissible assets.", "ref": "AAOIFI المعيار الشرعي 21"}, {"kind": "condition", "ar": "توزيع الفائض التأميني على المشتركين وفق اللائحة، ويقدّم المدير قرضًا حسنًا عند العجز.", "en": "Distribute underwriting surplus to participants per the rules; the operator provides a benevolent loan in deficit.", "ref": "AAOIFI المعيار الشرعي 26"}, {"kind": "condition", "ar": "إعادة التكافل مع جهات متوافقة، وتُقبل إعادة التأمين التقليدي للحاجة بضوابط الهيئة.", "en": "Retakaful with compliant providers; conventional reinsurance is accepted only of need under board rules.", "ref": "AAOIFI المعيار الشرعي 41 (إعادة التأمين)"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "زكاة الحبوب: نصابها خمسة أوسق، والعشر فيما سُقي بلا مؤونة ونصفه فيما سُقي بمؤونة.", "en": "Zakat on grain: nisab of five awsuq; a tenth when rain-fed and a twentieth when irrigated at cost.", "ref": "AAOIFI المعيار الشرعي 35", "strength": "ijma"}, {"kind": "condition", "ar": "السلم في الحبوب موصوفةً في الذمة جائز بشروطه.", "en": "Salam in grain described as a liability is permitted on its conditions.", "ref": "AAOIFI المعيار الشرعي 10", "strength": "ijma"}, {"kind": "prohibition", "ar": "بيع الحب قبل اشتداده على التبقية.", "en": "Selling grain before it hardens on condition that it stays in the field.", "ref": "النهي عن بيع الحب حتى يشتد", "strength": "nass"}, {"kind": "mandatory", "ar": "الصدق في الكيل والجودة، ومنع الاحتكار في أقوات الناس.", "en": "Honest measures and quality, and no hoarding of staple food.", "ref": "حديث «لا يحتكر إلا خاطئ»", "strength": "nass"}]$v$::jsonb
