UPDATE public.classification_standards SET requirements = $v$[{"kind": "prohibition", "ar": "بيع الثمار قبل بدوّ صلاحها إلا بشرط القطع.", "en": "Selling fruit before it ripens, unless on condition of immediate picking.", "ref": "النهي عن بيع الثمار حتى يبدو صلاحها", "strength": "nass"}, {"kind": "condition", "ar": "بدوّ الصلاح ظهور النضج وأمن العاهة، ويختلف باختلاف الثمر.", "en": "Ripening means signs of maturity and safety from blight, varying by fruit.", "ref": "كتب الفقه في بيع الثمار", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "زكاة الثمار الزكوية كالتمر والزبيب: العشر أو نصفه بعد بلوغ النصاب، ويُحال غيرها إلى منهجية الهيئة لاختلاف المذاهب.", "en": "Zakat on zakatable fruit such as dates and raisins: a tenth or a twentieth above nisab; other fruit follows the board's methodology given differences among schools.", "ref": "AAOIFI المعيار الشرعي 35", "strength": "ijma"}, {"kind": "condition", "ar": "المساقاة بجزء شائع معلوم من الثمر.", "en": "Musaqah for a known undivided share of the fruit.", "ref": "معاملة خيبر", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "منع الغش في الوزن والجودة وكتمان العيب.", "en": "No fraud in weight or quality, and no concealment of defects.", "ref": "حديث «من غشّنا فليس منّا»", "strength": "nass"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$A:زراعة الفاكهة$v$ AND requirements = $v$[{"kind": "prohibition", "ar": "بيع الثمار قبل بدوّ صلاحها إلا بشرط القطع.", "en": "Selling fruit before it ripens, unless on condition of immediate picking.", "ref": "النهي عن بيع الثمار حتى يبدو صلاحها"}, {"kind": "condition", "ar": "بدوّ الصلاح ظهور النضج وأمن العاهة، ويختلف باختلاف الثمر.", "en": "Ripening means signs of maturity and safety from blight, varying by fruit.", "ref": "كتب الفقه في بيع الثمار"}, {"kind": "mandatory", "ar": "زكاة الثمار الزكوية كالتمر والزبيب: العشر أو نصفه بعد بلوغ النصاب، ويُحال غيرها إلى منهجية الهيئة لاختلاف المذاهب.", "en": "Zakat on zakatable fruit such as dates and raisins: a tenth or a twentieth above nisab; other fruit follows the board's methodology given differences among schools.", "ref": "AAOIFI المعيار الشرعي 35"}, {"kind": "condition", "ar": "المساقاة بجزء شائع معلوم من الثمر.", "en": "Musaqah for a known undivided share of the fruit.", "ref": "معاملة خيبر"}, {"kind": "mandatory", "ar": "منع الغش في الوزن والجودة وكتمان العيب.", "en": "No fraud in weight or quality, and no concealment of defects.", "ref": "حديث «من غشّنا فليس منّا»"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "زكاة السائمة: تجب في البقر السائمة الحول إذا بلغت النصاب (في كل ثلاثين تبيع). والمعلوفة المعدّة للتجارة تُزكّى زكاة عروض التجارة، وتُحال التفاصيل إلى منهجية الهيئة.", "en": "Zakat on grazing cattle: due on cattle grazing for a year at nisab (a yearling per thirty). Fodder-fed cattle held for trade pay trade-goods zakat; details follow the board's methodology.", "ref": "AAOIFI المعيار الشرعي 35", "strength": "ijma"}, {"kind": "mandatory", "ar": "الرفق بالحيوان وحسن الملكة، وتحريم تعذيبه أو تجويعه.", "en": "Kindness and good care of animals; no torture or starvation.", "ref": "حديث «إن الله كتب الإحسان على كل شيء»", "strength": "nass"}, {"kind": "mandatory", "ar": "طيب العلف وخلوّه من المحرّم والنجس، وحبس الجلّالة حتى يطيب لحمها.", "en": "Wholesome feed free of prohibited and impure matter; jallalah animals are confined until their meat is wholesome.", "ref": "أحكام الجلّالة", "strength": "ijtihad"}, {"kind": "mandatory", "ar": "الذكاة الشرعية: أهلية الذابح، والتسمية، وإنهار الدم بقطع الحلقوم والمريء.", "en": "Shariah slaughter: a qualified slaughterer, invoking God's name, and letting blood by cutting the windpipe and oesophagus.", "ref": "OIC/SMIIC 1", "strength": "ijma"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$A:تربية الأبقار$v$ AND requirements = $v$[{"kind": "condition", "ar": "زكاة السائمة: تجب في البقر السائمة الحول إذا بلغت النصاب (في كل ثلاثين تبيع). والمعلوفة المعدّة للتجارة تُزكّى زكاة عروض التجارة، وتُحال التفاصيل إلى منهجية الهيئة.", "en": "Zakat on grazing cattle: due on cattle grazing for a year at nisab (a yearling per thirty). Fodder-fed cattle held for trade pay trade-goods zakat; details follow the board's methodology.", "ref": "AAOIFI المعيار الشرعي 35"}, {"kind": "mandatory", "ar": "الرفق بالحيوان وحسن الملكة، وتحريم تعذيبه أو تجويعه.", "en": "Kindness and good care of animals; no torture or starvation.", "ref": "حديث «إن الله كتب الإحسان على كل شيء»"}, {"kind": "mandatory", "ar": "طيب العلف وخلوّه من المحرّم والنجس، وحبس الجلّالة حتى يطيب لحمها.", "en": "Wholesome feed free of prohibited and impure matter; jallalah animals are confined until their meat is wholesome.", "ref": "أحكام الجلّالة"}, {"kind": "mandatory", "ar": "الذكاة الشرعية: أهلية الذابح، والتسمية، وإنهار الدم بقطع الحلقوم والمريء.", "en": "Shariah slaughter: a qualified slaughterer, invoking God's name, and letting blood by cutting the windpipe and oesophagus.", "ref": "OIC/SMIIC 1"}]$v$::jsonb;
