UPDATE public.classification_standards SET requirements = $v$[{"kind": "mandatory", "ar": "الذكاة الشرعية: أهلية الذابح (مسلم أو كتابي)، والتسمية، وقطع الحلقوم والمريء وإنهار الدم.", "en": "Shariah slaughter: a qualified slaughterer (Muslim or of the People of the Book), invoking God's name, and cutting the windpipe and oesophagus to let blood.", "ref": "OIC/SMIIC 1", "strength": "ijma"}, {"kind": "prohibition", "ar": "ما ذُبح على غير اسم الله أو مات خنقًا أو صعقًا قبل الذبح فهو ميتة.", "en": "Anything slaughtered in other than God's name, or killed by strangling or stunning before slaughter, is carrion.", "ref": "قوله تعالى: ﴿حُرّمت عليكم الميتة…﴾", "strength": "nass"}, {"kind": "mandatory", "ar": "فصل خطوط الإنتاج الحلال ومنع التلوث المتبادل، وخلو المضافات والأغلفة من المحرّم.", "en": "Separate halal lines and prevent cross-contamination, with additives and casings free of prohibited matter.", "ref": "OIC/SMIIC 1", "strength": "ijtihad"}, {"kind": "condition", "ar": "اللحوم المستزرعة مخبريًا: تُقبل بالشروط التي قررها مجمع الفقه في قراره 265، وتحال تفاصيلها إلى الهيئة.", "en": "Cultivated meat is accepted on the conditions set by fiqh academy resolution 265, with details referred to the board.", "ref": "قرار مجمع الفقه 265", "strength": "khilaf"}, {"kind": "mandatory", "ar": "الصدق في الوسم والتاريخ وبلد المنشأ وشهادة الحلال.", "en": "Truthful labelling, dates, origin and halal certification.", "ref": "OIC/SMIIC 1", "strength": "nass"}]$v$::jsonb
  WHERE level = 'activity' AND node_key = $v$C:تصنيع اللحوم والأسماك$v$ AND requirements = $v$[{"kind": "mandatory", "ar": "الذكاة الشرعية: أهلية الذابح (مسلم أو كتابي)، والتسمية، وقطع الحلقوم والمريء وإنهار الدم.", "en": "Shariah slaughter: a qualified slaughterer (Muslim or of the People of the Book), invoking God's name, and cutting the windpipe and oesophagus to let blood.", "ref": "OIC/SMIIC 1"}, {"kind": "prohibition", "ar": "ما ذُبح على غير اسم الله أو مات خنقًا أو صعقًا قبل الذبح فهو ميتة.", "en": "Anything slaughtered in other than God's name, or killed by strangling or stunning before slaughter, is carrion.", "ref": "قوله تعالى: ﴿حُرّمت عليكم الميتة…﴾"}, {"kind": "mandatory", "ar": "فصل خطوط الإنتاج الحلال ومنع التلوث المتبادل، وخلو المضافات والأغلفة من المحرّم.", "en": "Separate halal lines and prevent cross-contamination, with additives and casings free of prohibited matter.", "ref": "OIC/SMIIC 1"}, {"kind": "condition", "ar": "اللحوم المستزرعة مخبريًا: تُقبل بالشروط التي قررها مجمع الفقه في قراره 265، وتحال تفاصيلها إلى الهيئة.", "en": "Cultivated meat is accepted on the conditions set by fiqh academy resolution 265, with details referred to the board.", "ref": "قرار مجمع الفقه 265"}, {"kind": "mandatory", "ar": "الصدق في الوسم والتاريخ وبلد المنشأ وشهادة الحلال.", "en": "Truthful labelling, dates, origin and halal certification.", "ref": "OIC/SMIIC 1"}]$v$::jsonb;
UPDATE public.classification_standards SET requirements = $v$[{"kind": "condition", "ar": "الأصل التداوي بالمباح، ولا يُستعمل المحرّم إلا لضرورة مع انتفاء البديل.", "en": "Treatment with lawful substances is the rule; prohibited ones are used only of necessity without alternatives.", "ref": "قاعدة «الضرورات تبيح المحظورات»", "strength": "ijma"}, {"kind": "condition", "ar": "الاستحالة: ما تغيّرت حقيقته فالجمهور على طهارته وحِلّه، ويضيّقها الشافعية. تعتمد الهيئة المذهب المعمول به.", "en": "Transformation: most jurists deem a fully transformed substance pure and lawful, while Shafi'is restrict this. The board sets the approach followed.", "ref": "قرارات مجمع الفقه في الاستحالة", "strength": "khilaf"}, {"kind": "mandatory", "ar": "الإفصاح عن المكوّنات ذات الأصل المحرّم (كالكحول والجيلاتين) ونسبتها.", "en": "Disclose ingredients of prohibited origin (such as alcohol and gelatin) and their proportion.", "ref": "معايير SMIIC للدواء الحلال", "strength": "ijtihad"}, {"kind": "prohibition", "ar": "الغش في الجودة، واحتكار الأدوية الضرورية أو المغالاة فيها.", "en": "Quality fraud, and hoarding or overpricing essential medicines.", "ref": "حديث «لا يحتكر إلا خاطئ»", "strength": "nass"}]$v$::jsonb
